insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('cisleitaniin', 'Cisleitaniin', '', '', '', '', 'Cisleithanien', '[{"kategorie": "allg.", "text": "\"inoffizieller Name für die österreichische Reichshälfte der [[Habsburgermonarchie]] nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867\""}, {"kategorie": "", "text": "Es bezeichnete die Gebiete der [[Doppelmonarchie]], die westlich der Leitha, eines Nebenflusses der Donau, lagen. Diese Regionen standen unter der Verwaltung des österreichischen Kaisers und wurden oft auch als \"Die im Reichsrat vertretenen Königreiche und Länder\" bezeichnet"}, {"kategorie": "", "text": "Cisleithanien umfasste viele [[Kronländer]], darunter Österreich, Böhmen, Mähren, Galizien, Schlesien, und andere. Im Gegensatz dazu stand [[Transleithanien]], das die ungarische Reichshälfte bezeichnete, also die Gebiete östlich der Leitha, unter der Verwaltung des ungarischen Königs"}, {"kategorie": "", "text": "Cisleithanien hatte eine eigene Verwaltung, ein Parlament (den [[Reichsrat]]), und teilweise eigene Gesetze, war aber über den gemeinsamen Monarchen und bestimmte Ministerien (wie Außenpolitik, Kriegswesen, Finanzen) mit Transleithanien verbunden."}]'::jsonb, ''),
  ('transleitaniin', 'Transleitaniin', '', '', '', '', 'Transleithanien', '[{"kategorie": "allg.", "text": "\"inoffizieller Name für die ungarische Reichshälfte der [[Habsburgermonarchie]] nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867\""}, {"kategorie": "", "text": "Es bezeichnete die Gebiete, die östlich der Leitha, eines Nebenflusses der Donau, lagen. Der Begriff steht im Gegensatz zu [[Cisleithanien]], der österreichischen Reichshälfte, die westlich der Leitha lag"}, {"kategorie": "", "text": "Transleithanien umfasste vor allem das [[Königreich]] Ungarn sowie die ihm angeschlossenen Gebiete, wie Kroatien-Slawonien und Siebenbürgen"}, {"kategorie": "", "text": "Diese Gebiete hatten nach dem [[Ausgleich]] von 1867 weitgehende Autonomie und wurden von der ungarischen Regierung in Budapest verwaltet, während der ungarische König (in Personalunion auch Kaiser von Österreich) die oberste Autorität blieb"}, {"kategorie": "", "text": "Auch wenn Ungarn eine eigene Verfassung und Regierung hatte, blieben bestimmte Bereiche (wie Außenpolitik, Militär und Finanzen) zwischen Österreich und Ungarn gemeinsam geregelt"}, {"kategorie": "", "text": "Der Begriff \"Transleithanien\" wurde hauptsächlich in Verwaltung und Politik verwendet, um die territoriale Unterscheidung zwischen den beiden Reichsteilen Österreich-Ungarns zu verdeutlichen."}]'::jsonb, ''),
  ('reichsrood', 'Reichsrood', '', '', '', '', 'Reichsrat', '[{"kategorie": "allg.", "text": "\"Parlament der österreichischen Reichshälfte ([[Cisleithanien]]) in der [[Habsburgermonarchie]] nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867\""}, {"kategorie": "", "text": "Es war das gesetzgebende Organ der im Reichsrat vertretenen Königreiche und Länder, also der österreichischen [[Kronländer]]"}, {"kategorie": "", "text": "Der Reichsrat bestand aus zwei Kammern: (i) Herrenhaus: Die obere Kammer, in der hohe Adelige, Geistliche und vom Kaiser ernannte lebenslange Mitglieder saßen;  (ii) Abgeordnetenhaus: Die untere Kammer, in die Vertreter der Bevölkerung der einzelnen [[Kronländer]] durch Wahlen entsandt wurden"}, {"kategorie": "", "text": "Der Reichsrat war maßgeblich für die Gesetzgebung und die Vertretung der Interessen [[Cisleithaniens]] gegenüber der Regierung und dem Kaiser verantwortlich. Es hatte jedoch nur auf die österreichische Reichshälfte Einfluss, während in der ungarischen Reichshälfte das ungarische Parlament (der [[Reichstag]]) die legislativen Aufgaben übernahm"}, {"kategorie": "", "text": "Der Reichsrat existierte bis zum Ende der Habsburgermonarchie 1918 und war ein zentrales Element in der politischen Struktur [[Cisleithaniens]]."}]'::jsonb, ''),
  ('reichstoog', 'Reichstoog', '', '', '', '', 'Reichstag', '[{"kategorie": "allg.", "text": "\"Parlament der ungarischen Reichshälfte ([[Transleithanien]]) in der [[Habsburgermonarchie]] nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867\""}, {"kategorie": "", "text": "Der Reichstag stellte das legislative Organ des [[Königreichs]] Ungarn dar und war für die Gesetzgebung und die politische Vertretung der ungarischen Gebiete verantwortlich"}, {"kategorie": "", "text": "Der Reichstag bestand aus zwei Kammern: (i) Magnatentafel: Die obere Kammer, vergleichbar mit dem Herrenhaus in [[Cisleithanien]], in der hochrangige Adelige und hohe Kirchenvertreter saßen;  (ii) Repräsentantenhaus: Die untere Kammer, deren Abgeordnete von der Bevölkerung gewählt wurden"}, {"kategorie": "", "text": "Der Reichstag hatte weitreichende Kompetenzen in der ungarischen Reichshälfte, insbesondere in Bereichen wie Bildung, Recht und Verwaltung. Allerdings waren bestimmte Angelegenheiten (wie Außenpolitik, Militär und gemeinsame Finanzen) zwischen Österreich und Ungarn durch gemeinsame Ministerien geregelt, über die beide Parlamente, der Reichstag und der [[Reichsrat]], nur begrenzten Einfluss hatten"}, {"kategorie": "", "text": "Der Reichstag tagte in Budapest und war ein zentrales Element der politischen Autonomie Ungarns innerhalb der [[Doppelmonarchie]] Österreich-Ungarn."}]'::jsonb, ''),
  ('magnatntoofae', 'Magnatntoofä', '', '', '', '', 'Magnatentafel', '[{"kategorie": "allg.", "text": "\"obere Kammer des ungarischen Parlaments ([[Reichstag]]) in der [[Habsburgermonarchie]] nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867\""}, {"kategorie": "", "text": "Sie entsprach einem aristokratischen Oberhaus, vergleichbar mit dem [[Herrenhaus]] in [[Cisleithanien]], und bestand hauptsächlich aus Mitgliedern des ungarischen Hochadels, hochrangigen Geistlichen und anderen bedeutenden Persönlichkeiten, die entweder kraft ihres Standes oder durch Ernennung in die Magnatentafel berufen wurden"}, {"kategorie": "", "text": "Die Magnatentafel hatte zusammen mit dem Repräsentantenhaus, der unteren Kammer des ungarischen Parlaments, die Aufgabe, Gesetze zu verabschieden, die sich auf die ungarische Reichshälfte ([[Transleithanien]]) bezogen"}, {"kategorie": "", "text": "Während das Repräsentantenhaus die gewählten Vertreter der Bevölkerung umfasste, war die Magnatentafel ein Ort der Repräsentation der privilegierten gesellschaftlichen Gruppen, insbesondere des Adels und des Klerus"}, {"kategorie": "", "text": "Die Magnatentafel verlor an Bedeutung mit der zunehmenden Demokratisierung und wurde nach dem Ende der Habsburgermonarchie und der Gründung der ungarischen Republik 1918 abgeschafft."}]'::jsonb, ''),
  ('heanhaus', 'Heanhaus', '', '', '', '', 'Herrenhaus', '[{"kategorie": "allg.", "text": "\"obere Kammer des österreichischen [[Reichsrats]], dem Parlament der österreichischen Reichshälfte ([[Cisleithanien]]) in der [[Habsburgermonarchie]] nach dem [[Ausgleich]] von 1867\""}, {"kategorie": "", "text": "Das Herrenhaus entsprach einem aristokratischen Oberhaus und setzte sich aus Mitgliedern des Hochadels, hohen kirchlichen Würdenträgern sowie lebenslang ernannten Mitgliedern zusammen, die entweder aufgrund ihrer Position oder durch Ernennung durch den Kaiser in das Herrenhaus berufen wurden"}, {"kategorie": "", "text": "Die Mitglieder des Herrenhauses wurden nicht gewählt, sondern entweder kraft ihres Standes (wie Fürsten, Erzbischöfe, Bischöfe) oder aufgrund besonderer Verdienste berufen. Neben den erblichen Adelsmitgliedern konnte der Kaiser auch Bürgerliche aufgrund von herausragenden Leistungen in Politik, Wissenschaft oder Militär in das Herrenhaus ernennen"}, {"kategorie": "", "text": "Das Herrenhaus hatte zusammen mit dem Abgeordnetenhaus (der gewählten unteren Kammer) die Aufgabe, Gesetze zu diskutieren und zu verabschieden. Es vertrat insbesondere die Interessen des Adels und des Klerus, während das Abgeordnetenhaus die Interessen der Bevölkerung repräsentierte"}, {"kategorie": "", "text": "Mit dem Ende der [[Habsburgermonarchie]] 1918 und der Gründung der [[Republik]] Österreich wurde das Herrenhaus aufgelöst."}]'::jsonb, ''),
  ('kreiza', 'Kreiza', '', '', '', '', 'Kreuzer', '[{"kategorie": "allg.", "text": "\"kleine Währungseinheit, die in verschiedenen deutschsprachigen Ländern und Regionen, einschließlich der [[Habsburgermonarchie]], verwendet wurde. Er diente als Untereinheit des [[Guldens]], wobei in der [[Habsburgermonarchie]] 1 Gulden = 100 Kreuzer entsprach\""}, {"kategorie": "", "text": "Der Kreuzer war ursprünglich eine Silbermünze und wurde seit dem 13. Jahrhundert geprägt. Mit der Zeit entwickelte sich der Kreuzer zu einer gängigen Münze für alltägliche Transaktionen"}, {"kategorie": "", "text": "Der Kreuzer blieb bis zur [[Währungsreform]] von 1892 in [[Österreich-Ungarn]] im Umlauf, als der Gulden und damit auch der Kreuzer durch die [[Krone]] und den [[Heller]] ersetzt wurden"}, {"kategorie": "", "text": "Im täglichen Leben und bei kleineren Zahlungen spielte der Kreuzer eine bedeutende Rolle, ähnlich wie heute kleinere Münzeinheiten wie Cent oder Pfennig."}]'::jsonb, ''),
  ('alban', 'Alban', '', '', '', '', 'Albern', '[{"kategorie": "allg.", "text": "\"alte Siedlung im 11. Wiener Gemeindebezirk ([[Simmering]]=, die erstmals 1162 als \"Albrah\" urkundlich erwähnt wurde\""}, {"kategorie": "", "text": "Sie liegt nahe der Mündung des [[Donaukanals]] in die [[Donau]] und litt in der Vergangenheit häufig unter Überschwemmungen, besonders im 16. Jahrhundert. Die Bewohner erhielten vom Kaiser zeitweise Land als Entschädigung für verlorene Gebiete, die von der Donau weggespült wurden. Albern musste nach schweren Überschwemmungen im 18. Jahrhundert mehrmals neu aufgebaut werden"}, {"kategorie": "", "text": "Im Jahre 1892 wurde Albern im Zuge der [[Eingemeindung]] Wiens teilweise in den 11. Bezirk integriert. 1938, während des nationalsozialistischen Regimes, erfolgte die vollständige Eingemeindung nach Wien, zunächst in den damaligen 23. Bezirk Schwechat. Nach dem [[Zweiten]] Weltkrieg wurde Albern im Zuge territorialer Anpassungen 1954 endgültig dem 11. Bezirk zugeordnet"}, {"kategorie": "", "text": "Heute ist Albern vor allem für seinen [[Alberner]] Hafen bekannt, sowie für den [[Friedhof]] der Namenlosen, auf dem angeschwemmte Wasserleichen bestattet wurden"}, {"kategorie": "", "text": "Die Ostautobahn (A4) trennt Albern vom westlich angrenzenden [[Kaiserebersdorf]]."}]'::jsonb, ''),
  ('wintahoofn', 'Wintahoofn', '', '', '', '', 'Winterhafen', '[{"kategorie": "allg.", "text": "\"historischer Hafen in Wien, der sich am [[Donaukanal]] im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]) befindet\""}, {"kategorie": "", "text": "Ursprünglich wurde er als Schutz- und Liegehafen für Schiffe während der Wintermonate genutzt, wenn die [[Donau]] aufgrund von Eis oder Hochwasser schwer befahrbar war. Schiffe konnten hier sicher vor Anker gehen und die Winterzeit überdauern, weshalb der Hafen diesen Namen trägt"}, {"kategorie": "", "text": "Im Laufe der Zeit hat der Winterhafen seine Bedeutung für den aktiven Güterumschlag weitgehend verloren und wird heute vor allem für Freizeitschifffahrt und kleinere Schiffsanlegestellen genutzt. Er spielt eine weniger bedeutende Rolle im modernen Logistiknetzwerk Wiens, bleibt aber ein Teil der [[Wiener]] Hafeninfrastruktur und hat eine historische Bedeutung für die Schifffahrt der Stadt."}]'::jsonb, ''),
  ('boltzmanngossn', 'Boltzmanngossn', '', '', '', '', 'Boltzmanngasse', '[{"kategorie": "allg.", "text": "Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Sie wurde nach dem bekannten österreichischen Physiker und Philosophen Ludwig Boltzmann benannt, der bedeutende Beiträge zur Thermodynamik und Statistischen Mechanik leistete"}, {"kategorie": "", "text": "Die Gasse hat eine lange historische Entwicklung: 1778 hieß sie Am Spanischen Spitalberg, ab 1791 Spitalberggasse, und ab 1820 überwiegend Carlsgasse (nach Kaiser Karl VI., der das Spanische Spital errichten ließ). Von 1862 bis 1913 trug sie den Namen Waisenhausgasse, benannt nach dem von Joseph II. in das ehemalige Spanische Spital verlegten Waisenhaus"}, {"kategorie": "", "text": "Das Spanische Spital in der Boltzmanngasse 9 wurde 1718 von [[Karl]] VI. für seine spanischen und neapolitanischen Untertanen sowie ehemalige Kriegskameraden errichtet. Es war vor allem für jene Spanier gedacht, die ihn nach Wien begleiteten, nachdem sie für ihn im Spanischen Erbfolgekrieg gekämpft hatten und er nach dem Tod seines kinderlos verstorbenen Bruders [[Joseph]] I. im Jahr 1711 aus Spanien nach Wien zurückgekehrt war"}, {"kategorie": "", "text": "Die Boltzmanngasse liegt seit jeher in einem Viertel, das von zahlreichen akademischen und wissenschaftlichen Einrichtungen geprägt ist"}, {"kategorie": "", "text": "Die Konsularakademie befand sich an Nummer 16. Hier wurden in Wien einst die Diplomaten und Konsuln für den österreichischen Staatsdienst ausgebildet. Heute ist an dieser Stelle die Botschaft der Vereinigten Staaten von Amerika angesiedelt."}]'::jsonb, ''),
  ('schdruudlhofgossn', 'Schdruudlhofgossn', '', '', '', '', 'Strudlhofgasse', '[{"kategorie": "allg.", "text": "kurze Gasse im 9. Wiener Gemeindebezirk ([[Alsergrund]]), welche die [[Währinger]] Straße mit der tiefer gelegenen [[Liechtensteinstraße]] über die berühmte [[Strudlhofstiege]], eine monumentale Freitreppe (eröffnet 1910), verbindet"}, {"kategorie": "", "text": "Sie wurde nach dem Barockkünstler Peter Strudel benannt, der hier im 17. Jahrhundert seinen Wohnsitz hatte und eine Kunstakademie gründete"}, {"kategorie": "", "text": "Der Strudelhof war ein Anwesen, das 1690 von Peter Strudel, einem kaiserlichen Hof- und Kammermaler, erbaut wurde. Ursprünglich als Wohn- und Ateliergebäude errichtet, diente es später als Pestspital und wurde für verschiedene karitative Zwecke genutzt, unter anderem als Findelhaus. Teile des Strudelhofs wurden später abgerissen oder in Miethäuser umgewandelt"}, {"kategorie": "", "text": "Die Gasse ist Teil eines historischen Viertels und hat literarische Berühmtheit durch Heimito von Doderers Roman \"Die Strudlhofstiege oder Melzer und die Tiefe der Jahre\" erlangt."}]'::jsonb, ''),
  ('schdruudlhofschdiang', 'Schdruudlhofschdiang', '', '', '', '', 'Strudlhofstiege', '[{"kategorie": "allg.", "text": "monumentale Freitreppe im 9. Wiener Gemeindebezirk ([[Alsergrund]]), welche die [[Strudlhofgasse]] mit der tiefer gelegenen [[Liechtensteinstraße]] verbindet"}, {"kategorie": "", "text": "Die Strudlhofstiege wurde 1910 im Jugendstil erbaut und nach dem Barockkünstler Peter Strudel benannt, der in der Nähe lebte und den Strudelhof errichtete"}, {"kategorie": "", "text": "Der Strudelhof war ein Anwesen, das 1690 von Peter Strudel, einem kaiserlichen Hof- und Kammermaler, erbaut wurde. Ursprünglich als Wohn- und Ateliergebäude errichtet, diente es später als Pestspital und wurde für verschiedene karitative Zwecke genutzt, unter anderem als Findelhaus. Teile des Strudelhofs wurden später abgerissen oder in Miethäuser umgewandelt"}, {"kategorie": "", "text": "Die Strudlhofstiege ist ein beliebtes architektonisches Wahrzeichen Wiens und erlangte zusätzliche Bekanntheit durch Heimito von Doderers Roman \"Die Strudlhofstiege oder Melzer und die Tiefe der Jahre\""}, {"kategorie": "", "text": "Sie ist sowohl ein funktionales Element im Stadtbild als auch ein Kunstwerk mit kunstvollen Geländern, Wasserspielen und Grünanlagen."}]'::jsonb, ''),
  ('sechshaus', 'Sechshaus', '', '', '', '', 'Sechshaus', '[{"kategorie": "allg.", "text": "\"Stadtteil im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]])\""}, {"kategorie": "", "text": "Ursprünglich ein eigenständiges Dorf, wurde Sechshaus 1892 in den damals neu geschaffenen 14. Bezirk Rudolfsheim eingegliedert und gehört seit 1938 zum 15. Bezirk"}, {"kategorie": "", "text": "Der Stadtteil entstand um 1706 als Zeilensiedlung auf unbebautem Land zwischen der heutigen [[Sechshauser]] Straße und [[Ullmannstraße]] und wuchs schnell in Richtung des [[Wienflusses]]"}, {"kategorie": "", "text": "Sechshaus unterstand der Grundobrigkeit der Barnabiten zu St. Michael in Wien. Trotz Rückschlägen wie den napoleonischen Kriegen und Epidemien im 19. Jahrhundert entwickelte sich der Vorort zu einer wichtigen gewerblich-industriellen Gemeinde, bevor er durch die Revolution von 1848 einen wirtschaftlichen Rückgang erlebte"}, {"kategorie": "", "text": "Im Laufe der Zeit entwickelte sich Sechshaus zu einer Vorstadt von Wien und wurde 1892 in die Stadt eingemeindet"}, {"kategorie": "", "text": "Heute ist Sechshaus Teil des stark urbanisierten 15. Bezirks und geprägt von Wohn- und Gewerbegebieten."}]'::jsonb, ''),
  ('uimaunnschdrossn', 'Uimaunnschdrossn', '', '', '', '', 'Ullmannstraße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]])"}, {"kategorie": "", "text": "Sie verläuft in nord-südlicher Richtung und verbindet den [[Gürtel]] mit der [[Linken]] Wienzeile"}, {"kategorie": "", "text": "Die Straße wurde 1894 nach Josef Ullmann (1846-1890) benannt, einem Zuckerwarenfabrikanten, Bürgermeister und Ehrenbürger von Sechshaus"}, {"kategorie": "", "text": "Die Ullmannstraße ist heute eine bedeutende Verkehrsader mit zahlreichen Wohngebäuden, Geschäften und Dienstleistungsbetrieben, welche sich zu einem urbanen und funktionalen Teil des Wiener Stadtgefüges entwickelt hat"}, {"kategorie": "", "text": "Sie ist auch gut an den öffentlichen Verkehr angebunden, unter anderem durch die U-Bahnlinie U4, die die Straße an der Station der gegenüber liegenden [[Meidling]] Hauptstraße quert."}]'::jsonb, ''),
  ('pasteurgossn', 'Pasteurgossn', '', '', '', '', 'Pasteurgasse', '[{"kategorie": "allg.", "text": "\"Gasse im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Die Gasse ist benannt nach dem französischen Chemiker und Mikrobiologen Louis Pasteur"}, {"kategorie": "", "text": "Sie wurde 1895, ein Jahr nach seinem Tod, zu Ehren seiner bedeutenden wissenschaftlichen Leistungen benannt, insbesondere seiner Entdeckungen auf dem Gebiet der Mikrobiologie und der Entwicklung von Impfstoffen"}, {"kategorie": "", "text": "Die Pasteurgasse liegt in einem Gebiet, das von mehreren medizinischen und wissenschaftlichen Einrichtungen geprägt ist, darunter Einrichtungen des [[Allgemeinen]] Krankenhauses Wien (AKH) und der Universität Wien"}, {"kategorie": "", "text": "Die Pasteurgasse verläuft parallel zur [[Strudlhofgasse]], die zur [[Strudlhofstiege]] führt"}, {"kategorie": "", "text": "Beide Gassen sind Teil des urbanen und architektonisch interessanten Umfelds, das sich in der Nähe des [[Liechtensteinparks]] befindet"}, {"kategorie": "", "text": "Die Gasse ist heute von Wohnhäusern, Geschäften und Praxen geprägt und spiegelt die wissenschaftliche und medizinische Bedeutung der Umgebung wider."}]'::jsonb, ''),
  ('liichtnschdeinpark', 'Liichtnschdeinpark', '', '', '', '', 'Liechtensteinpark', '[{"kategorie": "allg.", "text": "\"Park des Liechtensteinschen Sommerpalais im 9. Wiener Gemeindebezirk ([[Alsergrund]]) im Stadtteil [[Rossau]]\""}, {"kategorie": "", "text": "Das Palais wurde 1711 von Johann Adam Andreas Fürst von Liechtenstein nach Plänen der Architekten Domenico Egidio Rossi und Domenico Martinelli erbaut"}, {"kategorie": "", "text": "Ursprünglich war der Park ein Barockgarten, entworfen von Jean Trehet, der im späten 18. Jahrhundert in einen Landschaftsgarten umgestaltet wurde"}, {"kategorie": "", "text": "Der Park ist für seine historischen Elemente bekannt, darunter eine um 1795 geschaffene Brunnenfigur von Franz Anton Zauner (eine Nereide mit Kind)"}, {"kategorie": "", "text": "Ursprünglich befand sich im unteren Teil des Parks ein von Johann Bernhard Fischer von Erlach gestalteter Pavillon namens \"Belvedere\", der jedoch später abgerissen und durch das Alserbachpalais ersetzt wurde"}, {"kategorie": "", "text": "Heute ist der Liechtensteinpark ein grünes Erholungsgebiet und Teil des Kulturdenkmals rund um das Palais"}]'::jsonb, ''),
  ('wasagossn', 'Wasagossn', '', '', '', '', 'Wasagasse', '[{"kategorie": "allg.", "text": "\"Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]]) im Stadtteil [[Rossau]]\""}, {"kategorie": "", "text": "Sie verläuft vom [[Schottenring]] bis in die Nähe des [[Liechtensteinparks]]  und ist Teil eines historischen Viertels, das von der Nähe zu mehreren bedeutenden Bildungseinrichtungen geprägt ist, darunter das Wasagymnasium und Einrichtungen der Universität Wien"}, {"kategorie": "", "text": "Die Wasagasse wurde 1862 nach Gustav Prinz von Wasa benannt, dem Sohn von König Gustav IV. von Schweden aus dem Haus Holstein-Gottorp. Nach der erzwungenen Abdankung seines Vaters im Jahr 1809 und dem Exil der Familie nahm Gustav 1829 den Titel \"Prinz von Wasa\" an, benannt nach der früheren schwedischen Dynastie der Wasa"}, {"kategorie": "", "text": "Gustav von Wasa diente in der österreichischen Armee, wo er 1836 zum Feldmarschall-Leutnant aufstieg und zeitweise in Wien residierte. Er erwarb 1860 ein Palais, das später als [[Wasapalais]] bekannt wurde, und ließ es 1862 erweitern"}, {"kategorie": "", "text": "Die Gasse, die seinen Namen trägt, liegt in der Nähe von historischen und kulturellen Einrichtungen, wie dem [[Palais]] Liechtenstein."}]'::jsonb, ''),
  ('wasapalais', 'Wasapalais', '', '', '', '', 'Wasapalais', '[{"kategorie": "allg.", "text": "\"historisches Palais in der Wasagasse 12 im 9. Wiener Gemeindebezirk ([[Alsergrund]]) im Stadtteil [[Rossau]]\""}, {"kategorie": "", "text": "Es wurde zwischen 1857 und 1860 nach Plänen von Peter Hofbauer für den kaiserlich-königlichen Kämmerer Friedrich Reichsfreiherr von und zu Dalberg erbaut"}, {"kategorie": "", "text": "Im Jahr 1860 wurde das Palais an Prinz Gustav von Wasa verkauft, der dort von 1873 bis 1877 lebte, nachdem er zuvor in der Wasagasse 2 gewohnt hatte"}, {"kategorie": "", "text": "Prinz Gustav von Wasa (*1799 – †1877) war der Sohn des abgesetzten schwedischen Königs Gustav IV. Adolf. Nach dem Thronverlust seiner Familie lebte er im Exil und nahm 1829 den Titel \"Prinz von Wasa\" an. Gustav diente in der österreichischen Armee und lebte viele Jahre in Wien"}, {"kategorie": "", "text": "Nach dem Prinzen diente das Palais unter anderem als Wohnsitz des Wiener Bürgermeisters Cajetan Felder, der dort am 30. November 1894 verstarb"}, {"kategorie": "", "text": "Das Palais ist ein bedeutendes Beispiel für den historischen Baustil des 19. Jahrhunderts in Wien. Es zeichnet sich durch eine frühhistoristische Fassadengestaltung mit gotisierenden Ornamenten aus, und die Einfahrt besitzt ein [[Platzlgewölbe]] (besondere Gewölbeform, bei der die Wölbung aus mehreren flachen, kuppelartigen Segmenten besteht. Es wirkt wie ein leicht gewölbtes Viereck oder Polygon und wird häufig bei Durchfahrten oder Eingängen verwendet) -"}]'::jsonb, ''),
  ('platzlgwoelb', 'Platzlgwölb', '', '', '', '', 'Platzlgewölbe', '[{"kategorie": "allg.", "text": "\"spezielle Gewölbeform, bei der die Wölbung aus mehreren flachen, kuppelartigen Segmenten besteht\""}, {"kategorie": "", "text": "Es ergibt ein leicht gewölbtes Viereck oder Polygon, das durch die Zusammensetzung der einzelnen Segmente entsteht"}, {"kategorie": "", "text": "Diese Bauweise ist besonders für kleinere, meist quadratische oder polygonale Grundrisse geeignet und findet häufig Anwendung bei Durchfahrten, Eingängen oder Vorhallen"}, {"kategorie": "", "text": "Das Platzlgewölbe erzeugt eine flachere und weniger steil ansteigende Wölbung im Vergleich zu klassischen [[Kuppelgewölben]], wodurch es eine ästhetisch ansprechende und gleichzeitig funktionale Deckenkonstruktion darstellt"}, {"kategorie": "", "text": "Ein typisches Beispiel für ein Platzlgewölb findet sich u.a. im [[Wasapalais]]."}]'::jsonb, ''),
  ('kolingossn', 'Kolingossn', '', '', '', '', 'Kolingasse', '[{"kategorie": "allg.", "text": "\"historische Gasse im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die von der [[Währinger]] Straße bis zur [[Rossauer]] Kaserne führt\""}, {"kategorie": "", "text": "Sie wurde im Jahr 1870 benannt, zur Erinnerung an den Sieg des österreichischen Feldmarschalls Leopold Joseph Graf Daun in der Schlacht bei Kolin 1757, in der er Friedrich den Großen von Preußen während des Siebenjährigen Krieges besiegte"}, {"kategorie": "", "text": "Die Straße ist Teil eines historisch bedeutsamen Viertels in der Nähe des [[Votivparks]] und des [[Wiener]] Rings und verbindet wichtige städtische Einrichtungen"}, {"kategorie": "", "text": "Heute zeichnet sich die Kolingasse vor allem durch ihre repräsentative Architektur im Stil der Wiener [[Gründerzeit]] aus."}]'::jsonb, ''),
  ('hoerlgossn', 'Hörlgossn', '', '', '', '', 'Hörlgasse', '[{"kategorie": "allg.", "text": "\"historische Gasse im 9. Wiener Gemeindebezirk ([[Alsergrund]]) im Stadtteil [[Rossau]]\""}, {"kategorie": "", "text": "Die Gasse wurde 1870 nach Josef Georg Hörl benannt, dem langjährigsten Bürgermeister Wiens (1773–1804)"}, {"kategorie": "", "text": "Hörl spielte eine bedeutende Rolle in der städtischen Verwaltung und unterstützte [[Joseph]] II. bei der Neuorganisation der kommunalen Verwaltung"}, {"kategorie": "", "text": "Zu den wichtigsten Errungenschaften seiner Amtszeit zählen die Pflasterung der Straßen Wiens, die Anlegung von Baumreihen auf dem [[Glacis]] sowie der Bau wichtiger Gebäude wie des [[Allgemeinen]] Krankenhauses (1784)"}, {"kategorie": "", "text": "Hörl war auch Zeuge kultureller Höhepunkte, wie der Eröffnung des [[Burgtheaters]] (1776) und der Ankunft von Mozart und Beethoven in Wien"}, {"kategorie": "", "text": "Heute zeichnet sich die Hörlgasse vor allem durch ihre repräsentative Architektur im Stil der Wiener [[Gründerzeit]] aus."}]'::jsonb, ''),
  ('auhof', 'Auhof', '', '', '', '', 'Auhof', '[{"kategorie": "allg.", "text": "\"Stadtteil im Westen Wiens im 13. Wiener Gemeindebezirk ([[Hietzing]]) und eine der Wiener Katastralgemeinden\""}, {"kategorie": "", "text": "Der Name geht auf einen seit dem Mittelalter nachgewiesenen Gutshof am nördlichen Rand des [[Lainzer]] Tiergartens zurück, der erstmals 1194 urkundlich als Forst- und Jagdhof \"Haviwa\" erwähnt wurde"}, {"kategorie": "", "text": "Der Auhof war bis ins 16. Jahrhundert im Besitz reicher Wiener Bürger und unterstand der Grundherrschaft der Johanniter"}, {"kategorie": "", "text": "1560 wurde er von Ferdinand I. erworben und diente bis 1919 als Amtssitz des kaiserlichen Forstmeisters sowie als Verwaltungssitz des Lainzer Tiergartens"}, {"kategorie": "", "text": "Der Auhof verlor im 20. Jahrhundert seine historische Bedeutung als Forsthof und wurde zunehmend von Industrieansiedlungen geprägt"}, {"kategorie": "", "text": "Die Westautobahn (A1) und das nahegelegene Einkaufszentrum Auhof wurden in der Umgebung errichtet"}, {"kategorie": "", "text": "Heute bezieht sich der Begriff Auhof auch auf eine Katastralgemeinde, die fast den gesamten Lainzer Tiergarten umfasst, unabhängig vom historischen Hof"}, {"kategorie": "", "text": "Bei der Schaffung von [[Groß-Wien]] am 15. Oktober 1938 wurde die Katastralgemeinde Auhof in Wien eingemeindet. Der Norden wurde dem 14. Bezirk ([[Penzing]]), der Lainzer Tiergarten dem damals noch bestehenden 25. Bezirk zugeteilt"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg und der Gebietsreform von 1954/1956 kam der Lainzer Tiergarten zum 13. Bezirk ([[Hietzing]]), und die Katastralgemeinde Auhof erhielt ihre heutigen Grenzen. Diese umfassen nun auch Teile des [[Bierhäuselbergs]] sowie vormals zur Katastralgemeinde [[Mauer]] gehörende Gebiete im südlichen Lainzer Tiergarten. 1960 wurde der Tiergarten durch Flächen aus Laab im Walde erweitert, die jedoch nicht zur Katastralgemeinde Auhof gehören."}]'::jsonb, ''),
  ('mauaboch', 'Mauaboch', '', '', '', '', 'Mauerbach', '[{"kategorie": "allg.", "text": "\"Bach in Niederösterreich und Wien sowie wichtigster Zubringer des [[Wienflusses]]\""}, {"kategorie": "", "text": "Der Mauerbach ist 12,42 km lang, entspringt am Tulbinger Kogel in der Marktgemeinde Tulbing und fließt durch die Marktgemeinde Mauerbach, wo er die Kartause Mauerbach passiert"}, {"kategorie": "", "text": "Im Wiener Abschnitt fließt er durch den 14. Bezirk ([[Penzing]]), insbesondere durch den Bezirksteil [[Hadersdorf]], und speist den Teich des [[Wasserschlosses]] Laudon"}, {"kategorie": "", "text": "Der Bach verläuft durch das Mauerbach-Rückhaltebecken und schließlich in das [[Retentionsbbecken]] Auhof, bevor er in den [[Wienfluss]] mündet"}, {"kategorie": "", "text": "Der Mauerbach führt das ganze Jahr über Wasser, mit einem durchschnittlichen Abfluss von 0,3 m³/s. Bei einem Jahrhunderthochwasser kann der Abfluss jedoch bis zu 64,7 m³/s ansteigen, was die Überflutungsgefahr stark minimiert."}]'::jsonb, ''),
  ('schdadlagossn', 'Schdadlagossn', '', '', '', '', 'Stadlergasse', '[{"kategorie": "allg.", "text": "ruhige, aber verkehrsgünstig gelegene Straße am Übergang von [[Unter-Sankt-Veit]] und [[Lainz]] im 13. Wiener Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Ihre historische Namensgebung erinnert an den Benediktiner und Komponisten Maximilian Stadler (1748-1833), der enge Verbindungen zu bedeutenden Musikern wie Mozart und Haydn pflegte und wichtige Beiträge zur österreichischen Musikgeschichte leistete"}, {"kategorie": "", "text": "Er spielte eine wichtige Rolle bei der Ordnung und Vollendung von Mozarts Nachlass und überwachte unter anderem die Drucklegung von Mozarts Requiem. Neben seiner musikwissenschaftlichen Tätigkeit komponierte Stadler zahlreiche kirchliche Werke, darunter Messen und das Oratorium „Die Befreiung Jerusalems“ (1816)"}, {"kategorie": "", "text": "Die Stadlergasse ist ein ruhiger, vorwiegend von Wohnhäusern gesäumter Straßenzug, der die Wohngebiete von [[Lainz]] und [[Unter-Sankt-Veit]] miteinander verbindet."}]'::jsonb, ''),
  ('lainz', 'Lainz', '', '', '', '', 'Lainz', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 13. Wiener Gemeindebezirk ([[Hietzing]]), der erstmals 1313 urkundlich erwähnt wurde (damals unter dem Namen \"Lventz\", abgeleitet vom slawischen Wort „loka“, was „auf der Wiese“ bedeutet)\""}, {"kategorie": "", "text": "Lainz war schon an der Wende vom 11. zum 12. Jahrhundert ein Grabenangerdorf (=Hauptstraße, die im Zentrum zu einem Anger [gemeindeeigene Wiesen- oder Weidefläche] verbreitert ist), das sich entlang der heutigen [[Lainzer]] Straße zwischen der [[Fasangarten-]] und [[Veitingergasse]] erstreckte. Lainz war jahrhundertelang eng mit dem benachbarten [[Speising]] verbunden, und beide Orte teilten sich eine Pfarre"}, {"kategorie": "", "text": "Lainz hatte eine bewegte Geschichte und wurde während der französischen Besatzung im Jahr 1809 geplündert. Trotz dieser und anderer Herausforderungen blieb Lainz ein eigenständiger Ort, bis es schließlich im Zuge der Wiener Stadterweiterung in den Jahren 1890/1892 gemeinsam mit [[Hietzing]] nach Wien eingemeindet wurde"}, {"kategorie": "", "text": "Heute ist Lainz ein beliebter Wohnbezirk, der vor allem für seine Nähe zu großen Grünflächen wie dem [[Lainzer]] Tiergarten bekannt ist, einem der größten Naherholungsgebiete Wiens. Der Stadtteil ist geprägt von einer Mischung aus historischen Bauten und modernen Wohnhäusern, die den gehobenen Charakter der Umgebung widerspiegeln."}]'::jsonb, ''),
  ('veitingagossn', 'Veitingagossn', '', '', '', '', 'Veitingergasse', '[{"kategorie": "allg.", "text": "\"historisch bedeutende Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), welche die Stadtteile [[Ober-St]].-Veit und [[Lainz]] miteinander verbindet\""}, {"kategorie": "", "text": "Die Straße ist nach einer historischen Flurbezeichnung benannt, dem sogenannten \"Veitinger Feld\" ab, das sich auf den benachbarten Ort Sankt Veit (heute [[Ober-St]].-Veit) bezieht"}, {"kategorie": "", "text": "Diese Flurbezeichnungen wurden früher für landwirtschaftlich genutzte Gebiete verwendet, die zum Dorf Sankt Veit gehörten, und der Name wurde später auf die Gasse übertragen. Sankt Veit war ursprünglich ein eigenständiges Dorf, das bereits im Mittelalter existierte. Das \"Veitinger Feld\" war ein landwirtschaftlich genutztes Gebiet, das zum Dorf gehörte und der Gasse später ihren Namen gab"}, {"kategorie": "", "text": "Die Straße ist Teil eines gehobenen Wohngebiets in Hietzing, das bekannt für seine ruhige, grüne Umgebung ist. In der Nähe der Veitingergasse befinden sich mehrere historische und moderne Villen sowie Wohnhäuser, die den exklusiven Charakter des Bezirks widerspiegeln. Die Nähe zu Grünflächen wie dem [[Lainzer]] Tiergarten trägt zur hohen Lebensqualität in der Umgebung bei."}]'::jsonb, ''),
  ('dollwiisn', 'Dollwiisn', '', '', '', '', 'Dollwiese', '[{"kategorie": "allg.", "text": "eine der beiden Skipisten in Wien, neben der [[Hohe-Wand-Wiese]] im 14. Wiener Gemeindebezirk ([[Penzing]])"}, {"kategorie": "", "text": "Die Dollwiese befindet sich im Bezirksteil [[Ober-Sankt-Veit]] im 13. Wiener Gemeindebezirk ([[Hietzing]]), nahe dem Sankt Veiter Tor des [[Lainzer]] Tiergartens"}, {"kategorie": "", "text": "Mit ihrer geringen Hangneigung wird sie als blaue Piste eingestuft"}, {"kategorie": "", "text": "Früher verfügte die Dollwiese über einen 120 Meter langen Schlepplift, der vom Sportamt der Stadt Wien betrieben wurde. Dieser wurde im Frühjahr 2012 durch einen Zauberteppich (Förderband) ersetzt, der seit 2013 nach Erteilung der Genehmigung in Betrieb ist"}, {"kategorie": "", "text": "Die Dollwiese ist gut erreichbar über die Buslinie 54A der [[Wiener]] Linien."}]'::jsonb, ''),
  ('schwoazschbaniaschdrossn', 'Schwoazschbaniaschdrossn', '', '', '', '', 'Schwarzspanierstraße', '[{"kategorie": "allg.", "text": "\"historisch bedeutsame Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Sie verläuft von der [[Währinger]] Straße bis zur [[Universitätsstraße]] und trägt ihren Namen aufgrund eines Klosters der spanischen Benediktiner, auch als \"Schwarzspanier\" bezeichnet, das im 17. Jahrhundert dort errichtet wurde. Obwohl das Kloster heute nicht mehr existiert, bleibt sein Einfluss auf die Namensgebung der Gasse bis heute spürbar"}, {"kategorie": "", "text": "Eines der bekanntesten Gebäude in der Schwarzspaniergasse ist das ehemalige Wohnhaus von Ludwig van Beethoven, in dem der berühmte Komponist im Jahr 1827 verstarb. Dieses Gebäude fungiert heute als Gedenkstätte, am Eingang zum Haus Nr. 15 befindet sich eine Gedenktafel"}, {"kategorie": "", "text": "Die Schwarzspaniergasse befindet sich in der Nähe der [[Universität]] Wien und ist somit ein zentraler und lebhafter Teil des Wiener Stadtbildes. Neben ihrer historischen Relevanz bietet die Straße durch ihre Nähe zu öffentlichen Einrichtungen und Sehenswürdigkeiten einen wichtigen kulturellen Beitrag zur Stadt und ihrer Geschichte."}]'::jsonb, ''),
  ('univeasitaetsschdrossn', 'Univeasitätsschdrossn', '', '', '', '', 'Universitätsstraße', '[{"kategorie": "allg.", "text": "\"historisch bedeutsame Straße Straße im 1. und 9. Wiener Gemeindebezirk ([[Innere]] Stadt und [[Alsergrund]]), die im Jahr 1873 nach der neuen [[Universität]] Wien benannt wurde, deren Bau von 1873 bis 1884 erfolgte\""}, {"kategorie": "", "text": "Im Mittelalter war das Gebiet der heutigen Universitätsstraße Teil der Vorstadt vor dem [[Schottentor]], die als \"Vorstadt zwischen den Mauern\" bekannt war"}, {"kategorie": "", "text": "Nach der [[Ersten]] Türkenbelagerung 1529 wurde das Areal zum [[Glacis]], einer offenen Verteidigungsfläche vor den Stadtmauern. Ab 1783 diente dieses Gebiet als Exerzier- und Paradeplatz am Josefstädter Glacis"}, {"kategorie": "", "text": "Mit der städtischen Entwicklung und Verbauung des Glacis ab 1870 wurde die Universitätsstraße zur Grenze der neuen [[Arkadenhäuser]], die rund um das Rathaus entstanden"}, {"kategorie": "", "text": "Die Universitätsstraße markiert somit eine wichtige historische und städtebauliche Veränderung im Wiener Stadtbild und liegt heute in unmittelbarer Nähe zu bedeutenden Gebäuden wie der [[Universität]] Wien und dem [[Votivpark]]"}, {"kategorie": "", "text": "Heute ist die Universitätsstraße eine belebte und wichtige Verkehrsverbindung im Zentrum von Wien, sowie - durch ihre Nähe zur Universität und anderen Bildungseinrichtungen - auch ein Knotenpunkt für Studenten und Akademiker."}]'::jsonb, ''),
  ('garnisongossn', 'Garnisongossn', '', '', '', '', 'Garnisongasse', '[{"kategorie": "allg.", "text": "\"Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die 1862 nach dem k. k. Garnisonsspital I (Militärgarnisonshauptspital I) benannt wurde\""}, {"kategorie": "", "text": "Dieses Spital, ursprünglich für militärische Zwecke errichtet, gehört seit 1920 zum [[Allgemeinen]] Krankenhaus der Stadt Wien (AKH)"}, {"kategorie": "", "text": "Die Gasse wurde um 1841/1845 neu eröffnet und trug zunächst den Namen Kirchengasse (1843–1862), benannt nach der nahegelegenen Garnisonskirche. Am 7. März 1892 wurde die Garnisongasse erweitert und der Abschnitt der Schwarzspanierstraße zwischen der Universitätsstraße und der Ferstelgasse hinzugefügt"}, {"kategorie": "", "text": "Heute verläuft die Garnisongasse durch einen Teil des 9. Bezirks, der durch seine Nähe zum AKH, zur Universität Wien und anderen wichtigen Institutionen von Bedeutung ist."}]'::jsonb, ''),
  ('feastlgossn', 'Feastlgossn', '', '', '', '', 'Ferstelgasse', '[{"kategorie": "allg.", "text": "\"historische Gasse im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die nach dem berühmten österreichischen Architekten Heinrich von Ferstel benannt wurde\""}, {"kategorie": "", "text": "Heinrich von Ferstel (*7. Juli 1828, Wien; † 14. Juli 1883, Grinzing) war ein bedeutender österreichischer Architekt des 19. Jahrhunderts, der maßgeblich zur Gestaltung Wiens im Historismus beigetragen hat"}, {"kategorie": "", "text": "Seinen Durchbruch als Architekt erlangte Ferstel 1854, als er den Wettbewerb für den Bau der [[Votivkirche]] gewann, deren Bau er 1856 begann. Im selben Jahr erhielt er den Auftrag für das Bank- und Börsengebäude (ehemalige Oesterreichisch-ungarische Bank) an der [[Freyung]], das 1860 vollendet wurde"}, {"kategorie": "", "text": "Heinrich von Ferstel verstarb 1883 in seiner Privatvilla in [[Grinzing]] und wurde auf dem [[Grinzinger]] Friedhof beigesetzt. Sein Mausoleum dort wurde nach einem eigenen Entwurf errichtet"}, {"kategorie": "", "text": "Die Ferstelgasse ist heute eine ruhige Wohnstraße, die in einem zentralen und historischen Teil Wiens liegt, unweit der [[Universität]] Wien und anderer bedeutender Gebäude und Straßen wie der [[Garnisongasse]] und der [[Schwarzspanierstraße]]"}]'::jsonb, ''),
  ('liibichgossn', 'Liibichgossn', '', '', '', '', 'Liebiggasse', '[{"kategorie": "allg.", "text": "\"kurze Gasse im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die nach dem deutschen Chemiker Justus Freiherr von Liebig benannt wurde\""}, {"kategorie": "", "text": "Liebig war einer der bedeutendsten Wissenschaftler des 19. Jahrhunderts und leistete wesentliche Beiträge zur Entwicklung der organischen Chemie und Agrarchemie"}, {"kategorie": "", "text": "Das Gebiet rund um die Liebiggasse gehörte im Mittelalter zur Vorstadt vor dem [[Schottentor]], ab dem 16. Jahrhundert zum [[Glacis]] und ab 1783 zum Exerzier- und Paradeplatz; 1870 wurde es zur Verbauung freigegeben"}, {"kategorie": "", "text": "Heute ist die Liebiggasse eine beliebte Wohn- und Geschäftsstraße im Universitätsviertel, geprägt von einer Mischung aus akademischen Institutionen, Restaurants, und Cafés, die die lebendige Atmosphäre dieses Viertels unterstreichen."}]'::jsonb, ''),
  ('grillparzerschdrossn', 'Grillparzerschdrossn', '', '', '', '', 'Grillparzerstraße', '[{"kategorie": "allg.", "text": "\"Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die nach dem berühmten österreichischen Dramatiker und Schriftsteller Franz Grillparzer benannt wurde\""}, {"kategorie": "", "text": "Grillparzer war einer der bedeutendsten Vertreter der österreichischen Literatur im 19. Jahrhundert, bekannt für seine klassischen Dramen (\"König Ottokars Glück und Ende\", \"Ein Bruderzwist im Hause Habsburg\", \"Die Jüdin von Toledo\") und literarischen Werke, die das kulturelle Leben Wiens stark prägten"}, {"kategorie": "", "text": "Im Bereich der Grillparzerstraße grenzten im Mittelalter die Vorstädte vor dem [[Widmer-]] und dem [[Schottentor]] aneinander; 1783-1870 erstreckte sich auf diesem Terrain der Exerzier- und Paradeplatz"}, {"kategorie": "", "text": "Die Grillparzerstraße befindet sich in der Nähe bedeutender Wiener Sehenswürdigkeiten wie dem Wiener [[Rathaus]], dem Wiener [[Landesgericht]] für Strafsachen und der Wiener [[Ringstraße]]"}, {"kategorie": "", "text": "Sie liegt in einem repräsentativen Teil der Stadt, umgeben von historischen Gebäuden, die sowohl Büros als auch Wohnungen beherbergen. Aufgrund ihrer zentralen Lage und der Nähe zu kulturellen Institutionen ist sie Teil des pulsierenden Lebens der Wiener Innenstadt."}]'::jsonb, ''),
  ('hacking', 'Hacking', '', '', '', '', 'Hacking', '[{"kategorie": "allg.", "text": "\"historisch bedeutender Stadtteil Wiens, der sich am [[Wienfluss]] am westlichen Ende des breiten [[Wientals]] befindet\""}, {"kategorie": "", "text": "Seit der Eingemeindung in den Jahren 1890/1892 ist Hacking Teil des 13. Wiener Gemeindebezirks ([[Hietzin]])g und bildet eine eigene Katastralgemeinde. Ein kleiner Teil des Gebiets greift auf das linke Ufer des Wienflusses über und gehört zum 14. Bezirk Penzing, insbesondere in der Nähe der [[Zufferbrücke]], in deren Nähe sich früher die Hackinger Mühle befand"}, {"kategorie": "", "text": "Die Geschichte Hackings reicht weit zurück: Der Ort wird erstmals 1156 urkundlich erwähnt (\"Hakkingin\") und war ursprünglich ein Weiler am Fuß des ehemaligen Schlosshügels, der sich gegen den [[Himmelhof]] erstreckte. Eine zeilenartige Erweiterung der Siedlung reichte bis zur [[Auhofstraße]] und zur [[Nikolaikapelle]], die an der Mauer des [[Lainzer]] Tiergartens liegt"}, {"kategorie": "", "text": "1176 wurde Hacking in Grenzkämpfen zerstört, und im Jahr 1217 wird ein Heinrich von Hacking erwähnt. Mitte des 13. Jahrhunderts erscheint der Ort in einer Schenkungsurkunde, die einen Otto von Hacking nennt. Der Ort Hacking war damals ein Lehen, das von Albrecht III. 1388 an Hertlein von Herzogbierbaum und 1411 von Albrecht V. an Hans Stupfenweicher gegeben wurde. Die Familie der Hackinger lässt sich bis zu ihrem Aussterben im Jahr 1494 nachweisen"}, {"kategorie": "", "text": "1529 wurde Hacking im Zuge der [[Ersten]] Türkenbelagerung Wiens zerstört, und auch die [[Zweite]] Türkenbelagerung von 1683 hinterließ schwere Schäden. Maria Theresia ließ auf dem Gelände Maulbeerbäume pflanzen, um die Seidenraupenzucht zu fördern, doch dieser Versuch war nur in benachbarten Orten wie [[St]]. Veit erfolgreich"}, {"kategorie": "", "text": "Insgesamt hat sich Hacking, obwohl es wiederholt unter Zerstörungen litt, allmählich entwickelt und besitzt heute, eingebettet in den Wienerwald und nahe dem Lainzer Tiergarten, eine ruhige, grüne Wohnlage. Historische Bauten wie die Überreste der früheren Gutsherrschaften und Kapellen prägen das Bild der Region."}]'::jsonb, ''),
  ('nikolaikapoeoen', 'Nikolaikapöön', '', '', '', '', 'Nikolaikapelle', '[{"kategorie": "allg.", "text": "\"einer der ältesten Sakralbauten Wiens, welcher sich im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Stadtteil [[Hacking]], nahe dem Nikolaitor am Rande des Lainzer Tiergartens, befindet\""}, {"kategorie": "", "text": "Ursprünglich dem heiligen Nikolaus geweiht, ist sie heute dem heiligen Eustachius gewidmet"}, {"kategorie": "", "text": "Die Kapelle wurde vermutlich gegen Ende des 12. Jahrhunderts erbaut und 1321 erstmals urkundlich erwähnt. Sie steht inmitten eines erhaltenen Wall-Graben-Systems, was darauf hindeutet, dass sie einst Teil einer hochmittelalterlichen Burganlage war. Der Name \"Nikolaikapelle\" leitet sich vom heiligen Nikolaus ab, wobei \"Nikolai\" der Genitiv von Nikolaus im Lateinischen ist"}, {"kategorie": "", "text": "Nach einem Grundtausch 1833 wurde das Gelände samt Kapelle in den [[Lainzer]] Tiergarten integriert. [[Erzherzog]] Ludwig ließ die Nikolaikapelle von 1835 bis 1837 wieder instand setzen. Sie erhielt dabei ihr heutiges klassizistisches Aussehen. Der Altar im Inneren stammte ursprünglich aus der Josephskapelle der [[Hofburg]] und wurde bei der Renovierung aufgestellt. Seitdem diente die Kapelle als kaiserliche Jagdkapelle und wurde dem heiligen Eustachius geweiht"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg, im Jahr 1945, wurde die Kapelle geplündert und verlor ihre Ausstattung. In den letzten Jahren wurde die Bausubstanz restauriert. Ihr heutiges Erscheinungsbild, einschließlich des Halbwalmdachs und des geschwungenen Giebels, geht auf die Renovierung in den Jahren 1835 bis 1837 zurück"}, {"kategorie": "", "text": "Seit etwa 300 Jahren wird jährlich um den 20. September herum eine Eustachiusmesse gefeiert, entweder vor der Nikolaikapelle oder in der Kirche von [[Mariabrunn]]"}]'::jsonb, ''),
  ('schlossbeaggossn', 'Schlossbeaggossn', '', '', '', '', 'Schlossberggasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), die sich durch den Stadtteil [[Hacking]] erstreckt\""}, {"kategorie": "", "text": "Die Straße ist nach dem nahegelegenen Schlossberg benannt, auf dem sich einst eine mittelalterliche Burg befand, die zum historischen Siedlungskern von Hacking gehörte. Der Schlossberg war ein markanter Hügel, der das Gebiet prägte und auf dem im Laufe der Geschichte mehrere Gutsherren residierten"}, {"kategorie": "", "text": "Im Zuge der Türkenbelagerungen in den Jahren 1529 und 1683 wurde die Schlossanlage schwer beschädigt. Trotz dieser Zerstörungen wurde das \"Hackinger Schlössel\" 1722 teilweise wieder aufgebaut, als es sich im Besitz von Franz Albert Freiherr von Kletzl befand"}, {"kategorie": "", "text": "Die Straße führt durch eine gehobene Wohngegend, die von Villen und Einfamilienhäusern geprägt ist, mit einer Mischung aus historischen Bezügen und modernem Lebensstil in der Nähe von Naturgebieten wie dem [[Lainzer]] Tiergarten"}, {"kategorie": "", "text": "In der Schlossberggasse befindet sich auch der [[Dominikanerinnenkonvent]] Hacking, ein bedeutendes religiöses und kulturelles Zentrum in der Umgebung, das im 19. Jahrhundert gegründet wurde."}]'::jsonb, ''),
  ('zuffabruckn', 'Zuffabruckn', '', '', '', '', 'Zufferbrücke', '[{"kategorie": "allg.", "text": "Brücke über den [[Wienfluss]], die die Wiener Gemeindebezirke [[Hietzing]] (13. Bezirk) und [[Penzing]] (14. Bezirk) miteinander verbindet"}, {"kategorie": "", "text": "Sie wurde am 6. November 1919 nach dem Brückenbauingenieur Josef Zuffer (1850–1909) benannt, der für seine Verdienste im Brückenbau geehrt wurde"}, {"kategorie": "", "text": "Die Zufferbrücke befindet sich im Stadtteil [[Hacking]] und ist ein wichtiger Verkehrsknotenpunkt zwischen den beiden Bezirken. Historisch betrachtet gehört ein kleiner Teil des Gebiets von Hacking, in dem sich die Brücke befindet, auch zum 14. Bezirk ([[Penzing]])"}, {"kategorie": "", "text": "Die Brücke hat sowohl verkehrstechnisch als auch historisch Bedeutung für die Region, da sie seit ihrer Errichtung eine wichtige Verbindung über den Wienfluss darstellt."}]'::jsonb, ''),
  ('schbeising', 'Schbeising', '', '', '', '', 'Speising', '[{"kategorie": "allg.", "text": "\"Stadtteil im 13. Wiener Gemeindebezirk ([[Hietzing]]) und eine der 89 Wiener Katastralgemeinden Wiens\""}, {"kategorie": "", "text": "Bis zur Eingemeindung im Jahr 1892 war Speising eine eigenständige Vorortgemeinde. Der historische Ortskern von Speising lässt sich im Bereich der heutigen [[Gallgasse]] finden"}, {"kategorie": "", "text": "Die erste urkundliche Erwähnung von Speising stammt aus dem Jahr 1355. In dieser Zeit schenkte Rudolf IV. den Ort der von ihm gegründeten Propstei St. Stephan. [[Herzog]] Albrecht V. übergab Speising im Jahr 1411 den Brüdern Peter und Alexius Chrudner als Lehen"}, {"kategorie": "", "text": "Aufgrund seiner ungeschützten Lage war Speising in der Vergangenheit stark von Kriegseinwirkungen betroffen, insbesondere während der [[Ersten]] Türkenbelagerung im Jahr 1529, als die Bevölkerung erheblich zu leiden hatte"}, {"kategorie": "", "text": "Nach der Eingemeindung Speisings in den 13. Bezirk Hietzing setzte eine umfangreiche Bautätigkeit ein, die das Bild des Ortes stark veränderte. Ein wesentlicher Auslöser dieser Entwicklung war der Bau von bedeutenden sozialen und medizinischen Einrichtungen auf dem Gebiet von Speising, darunter ein Waisenhaus, ein Taubstummeninstitut, die Rothschildstiftung sowie das Jubiläums-Spital (heute \"Orthopädisches Spital Speising\"). Diese Einrichtungen trugen dazu bei, dass Speising im Laufe des 20. Jahrhunderts dicht verbaut wurde und sich von einem Bauerndorf zu einem städtischeren Gebiet entwickelte"}, {"kategorie": "", "text": "Heute ist Speising ein Teil des noblen Bezirks Hietzing und zeichnet sich durch seine ruhige Wohnlage und seine historische Bedeutung aus."}]'::jsonb, ''),
  ('goigossn', 'Goigossn', '', '', '', '', 'Gallgasse', '[{"kategorie": "allg.", "text": "\"historische Gasse im Herzen des Stadtteils [[Speising]]  im 13. Wiener Gemeindebezirk ([[Hietzing]])\""}, {"kategorie": "", "text": "Die Gallgasse wurde am 12. Juli 1894 nach Sebastian Gall benannt, einem Hausbesitzer, Gemeinderat von Speising (1870-1888) und Wohltäter, der im Jahr 1888 verstarb. Gall war bekannt für sein soziales Engagement in der Gemeinde Speising, weshalb ihm zu Ehren die Straße nach ihm benannt wurde"}, {"kategorie": "", "text": "Im franziszäischen Kataster, einer frühen Form des Grundstückskatasters, ist die Gallgasse fast unverbaut dargestellt, was zeigt, dass sich der Straßenverlauf erst allmählich entwickelte"}, {"kategorie": "", "text": "Die meisten der heutigen Gebäude in der Gallgasse stammen aus der Mitte des 19. Jahrhunderts. Im Gegensatz zur benachbarten [[Speisinger]] Straße, wo ältere Gebäude häufig durch Bauwerke aus dem späten 19. und 20. Jahrhundert ersetzt wurden, hat sich in der Gallgasse ein geschlossenes Ensemble aus dieser Zeit erhalten. Dies verleiht der Straße einen besonderen historischen Charme und macht sie zu einem Beispiel für die städtebauliche Entwicklung von Speising in dieser Periode"}, {"kategorie": "", "text": "Die Gallgasse spiegelt somit einen Teil der ländlichen Vergangenheit von Speising wider und zeichnet sich durch ihren historischen Gebäudebestand aus, der überwiegend aus dem 19. Jahrhundert stammt."}]'::jsonb, ''),
  ('invalidnhauskiachn', 'Invalidnhauskiachn', '', '', '', '', 'Invalidenhauskirche', '[{"kategorie": "allg.", "text": "\"römisch-katholisches Kirchengebäude im Bezirksteil [[Speising]] im 13. Wiener Gemeindebezirk ([[Hietzing]]) an der [[Fasangartengasse]] 101\""}, {"kategorie": "", "text": "Die Invalidenhauskirche ist eine Militärpfarrkirche, die dem heiligen Johannes Nepomuk geweiht ist und nach Plänen des Architekten Hans Schneider errichtet wurde. Sie steht inmitten einer Anlage, die für Militärinvalide gebaut wurde, die zuvor bis 1909 im Invalidenhaus auf der [[Landstraße]] untergebracht waren"}, {"kategorie": "", "text": "Die Kirche wurde am 5. Mai 1910 geweiht und zeichnet sich durch ihre zentrale Bauweise auf einem quadratischen Grundriss aus. Besonders bemerkenswert ist die architektonische Gestaltung der südlichen Eingangsseite. Das Patrozinium (Schutzheilige der Kirche) wurde von der Kapelle des alten Invalidenhauses übernommen"}, {"kategorie": "", "text": "Die Altarwand wird von einer Kreuzigungsgruppe (um 1750) dominiert, die aus Skulpturen von Maria und Johannes besteht. Die Tabernakeltür ist mit einem Relief der Kreuzabnahme Christi geschmückt, das von dem berühmten Bildhauer Georg Raphael Donner stammt und auf 1735 datiert wird. Rechts vom Altar befindet sich eine barocke Holzstatue des heiligen Johannes Nepomuk, die laut Überlieferung einst am [[Alser]] Bach stand und das Ziel von kleinen Wallfahrten war"}, {"kategorie": "", "text": "Ursprünglich wurde die Kirche bis 1918 von Militärgeistlichen betreut, danach übernahmen Weltpriester diese Aufgabe. Am 1. Januar 1955 wurde sie dann offiziell eine eigenständige Pfarre. Nachdem die nahegelegene Kirche St. Hemma zur Pfarrkirche erhoben wurde, wurde die Invalidenhauskirche zur Filialkirche. Auf Wunsch des Bundesheeres wurde die Invalidenhauskirche 1987 zur Pfarrkirche der Militärpfarre Wien ernannt"}, {"kategorie": "", "text": "Im selben Gebäude wie die Kirchenräume befindet sich auch ein Ehrensaal, der patriotischen Gedenkzwecken dient. Hier gibt es eine Erinnerungstafel an die Anwesenheit von Kaiser [[Franz]] Joseph I. bei der Einweihung der Kirche. Der Saal enthält mehrere bedeutende Großgemälde, darunter eine Kopie des Schlachtengemäldes [[Schlacht bei Aspern]] von Johann Peter Krafft, dessen Original im [[Heeresgeschichtlichen]] Museum aufbewahrt wird."}]'::jsonb, ''),
  ('fasangoatn', 'Fasangoatn', '', '', '', '', 'Fasangarten', '[{"kategorie": "allg.", "text": "historischer Teil des [[Schönbrunner]] Schlossparks von Schönbrunn im 13. Wiener Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Der Fasangarten liegt südlich der [[Gloriette]] und wurde ursprünglich zur Haltung von Fasanen genutzt, die für die kaiserlichen Jagden im Schönbrunner Park vorgesehen waren. Der Fasangarten war somit ein Jagdgebiet, das den Mitgliedern des kaiserlichen Hofes zur Verfügung stand"}, {"kategorie": "", "text": "Nach dem Ende der [[österreichisch-ungarischen]] Monarchie im Jahr 1918 verlor der Fasangarten seine ursprüngliche Funktion und wurde teilweise als Sportplatz genutzt"}, {"kategorie": "", "text": "Im Jahr 1938, nach dem [[Anschluss]] Österreichs an das nationalsozialistische Deutschland, errichteten die nationalsozialistischen Behörden auf diesem Gelände die Fasangartenkaserne, die bis in die Nachkriegszeit als militärische Einrichtung genutzt wurde (heute [[Maria-Theresien-Kaserne]])"}, {"kategorie": "", "text": "Heute erinnert der Name Fasangarten an diese historische Nutzung und ist im Wiener Stadtbild durch Straßennamen wie die [[Fasangartengasse]] erhalten. Der Fasangarten ist eng mit der Geschichte des [[Schlossparks]] Schönbrunn und den kaiserlichen Jagdtraditionen verbunden."}]'::jsonb, ''),
  ('menascherii', 'Menascherii', '', '', '', '', 'Menagerie', '[{"kategorie": "wörtlich", "text": "\"Ménagerie\" (vom französischen „ménagerie“= Sammlung oder Ausstellung exotischer Tiere)"}, {"kategorie": "allg.", "text": "\"Die Menagerie im [[Schönbrunner]] Schlosspark, heute bekannt als der [[Tiergarten]] Schönbrunn, ist der älteste noch bestehende Zoo der Welt\""}, {"kategorie": "", "text": "Ursprünglich wurde die Menagerie im Jahr 1752 von Kaiser [[Franz]] I. Stephan von Lothringen, dem Ehemann von [[Maria]] Theresia, gegründet. Die Menagerie diente zunächst als kaiserliche Sammlung exotischer Tiere und war Teil des barocken Schönbrunner Schlossgartens"}, {"kategorie": "", "text": "Der Begriff \"Menagerie\" bezeichnet ursprünglich eine Sammlung seltener oder exotischer Tiere, die häufig von Fürsten oder Königen gehalten wurden, um ihren Wohlstand und ihre Macht zu demonstrieren. In der Schönbrunner Menagerie waren Tiere aus aller Welt zu sehen, die von den weitreichenden Handels- und Diplomatiebeziehungen des [[Habsburgerreichs]] stammten"}, {"kategorie": "", "text": "Die Menagerie war anfangs nur für den Kaiserhof und dessen Gäste zugänglich. Später wurde sie der Öffentlichkeit zugänglich gemacht und entwickelte sich zu einem wissenschaftlichen Zentrum für Zoologie und Naturschutz. Der Tiergarten Schönbrunn ist heute eine moderne zoologische Einrichtung, die sich dem Schutz bedrohter Arten, der Forschung und der Bildung widmet"}, {"kategorie": "", "text": "Mit seiner langen Geschichte und seiner barocken Architektur bleibt die Menagerie ein bedeutendes Zeugnis der kaiserlichen Pracht und des Interesses an der Naturwissenschaft im 18. Jahrhundert. Der Tiergarten Schönbrunn ist ein wichtiger Teil des UNESCO-Weltkulturerbes Schloss Schönbrunn und ein beliebtes Ausflugsziel für Besucher aus aller Welt."}]'::jsonb, ''),
  ('belvedeagoatn', 'Belvedeagoatn', '', '', '', '', 'Belvederegarten', '[{"kategorie": "allg.", "text": "\"prachtvolle Gartenanlage des [[Schlosses]] Belvedere im 3. Wiener Gemeindebezirk ([[Landstraße]]) an der Adresse: [[Prinz-Eugen-Straße]] 27 bzw. [[Rennweg]] 6\""}, {"kategorie": "", "text": "Der Garten wurde bereits kurz nach dem Grundstückskauf um 1700 angelegt und gehört somit zu den ältesten Teilen der gesamten Schlossanlage. Seine Gestaltung war bis 1725 abgeschlossen"}, {"kategorie": "", "text": "Der Garten ist ein herausragendes Beispiel barocker Gartenkunst und ein zentrales Element des Schlosses Belvedere, das für den Feldherrn Prinz Eugen von Savoyen errichtet wurde"}, {"kategorie": "", "text": "Die besondere topographische Lage des Gartens bestimmt seine Gliederung: Das Obere Belvedere liegt etwa 23 Meter höher als das Untere Belvedere, weshalb der Garten in drei Ebenen unterteilt ist: das obere, mittlere und untere Parterre. Diese Niveauunterschiede werden durch zwei Kaskadenbrunnen überwunden, die reich mit Skulpturen verziert sind"}, {"kategorie": "", "text": "Im Belvederegarten befinden sich insgesamt zwölf Brunnen, die zusammen mit zahlreichen Statuen und Skulpturen ein skulpturales Programm bilden, das typisch für barocke Gartenanlagen ist. Die kunstvolle Gestaltung und die symmetrische Anordnung der Parterres und Brunnen unterstreichen den repräsentativen Charakter des Gartens"}, {"kategorie": "", "text": "Seit 1780 ist der Belvederegarten der Öffentlichkeit zugänglich. In diesem Jahr übernahm [[Joseph]] II. nach dem Tod seiner Mutter Maria Theresia die Alleinregentschaft über Österreich. Die Anlage ist heute Teil des UNESCO-Weltkulturerbes, gemeinsam mit dem [[Schloss]] Belvedere und seinen historischen Gebäuden."}]'::jsonb, ''),
  ('fasangoatngossn', 'Fasangoatngossn', '', '', '', '', 'Fasangartengasse', '[{"kategorie": "allg.", "text": "\"historische Straße Straße im 12. und 13. Wiener Gemeindebezirk ([[Meidling]] und [[Hietzing]]), welche die Stadtteile [[Hetzendorf]], [[Lainz]] und [[Speising]] miteinander verbindet\""}, {"kategorie": "", "text": "Sie wurde am 10. Juli 1894 vom Wiener Stadtrat nach dem nahegelegenen Schönbrunner [[Fasangarten]] benannt wurde, einem südlich der Gloriette gelegenen Teil des Schlossparks von [[Schönbrunn]], der in der Zeit der Monarchie zu Jagdzwecken genutzt wurde. Ursprünglich diente der Fasangarten zur Haltung von Fasanen für die kaiserlichen Jagden, weshalb er diesen Namen trägt"}, {"kategorie": "", "text": "Nach dem Ende der Monarchie im Jahr 1918 wurde das Areal des Fasangartens teilweise als Sportplatz genutzt. Nach dem [[Anschluss]] Österreichs im Jahr 1938 errichteten die nationalsozialistischen Behörden auf diesem Gelände die Fasangartenkaserne, eine militärische Einrichtung (heute [[Maria-Theresien-Kaserne]])"}, {"kategorie": "", "text": "Die Fasangartengasse verläuft heute durch ein ruhiges Wohngebiet, das von historischen Bezügen und der Nähe zum Schlosspark Schönbrunn geprägt ist. Sie verbindet mehrere bedeutende Orte in Hietzing und führt unter anderem auch an der [[Invalidenhauskirche]] (Militärpfarrkirche) vorbei, was ihre kulturelle und historische Bedeutung im Bezirk unterstreicht."}]'::jsonb, ''),
  ('heamesschdrossn', 'Heamesschdrossn', '', '', '', '', 'Hermesstraße', '[{"kategorie": "allg.", "text": "bedeutende Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), im Bereich von [[Speising]] und [[Lainz]]"}, {"kategorie": "", "text": "Sie wurde am 13. Juli 1894 nach der [[Hermesvilla]] und der darin befindlichen Hermesstatue im [[Lainzer]] Tiergarten benannt. Zuvor trug die Straße den Namen Tiergartenstraße, in Anlehnung an den angrenzenden [[Lainzer]] Tiergarten, einem großen Naherholungsgebiet in Wien"}, {"kategorie": "", "text": "Die Hermesvilla, auch als das \"Schloss der Träume\" bekannt, wurde von Kaiser [[Franz]] Joseph I. für seine Frau, Kaiserin Elisabeth ([[Sisi]]), als Rückzugsort erbaut. Sie erhielt ihren Namen durch die dort befindliche Statue des Götterboten Hermes, die den Eingang der Villa ziert"}, {"kategorie": "", "text": "Die Straße verbindet den Lainzer Tiergarten mit dem städtischen Bereich von Speising und Lainz und spielt eine wichtige Rolle als Verkehrsverbindung zur Hermesvilla und den umliegenden Grünflächen"}, {"kategorie": "", "text": "Entlang der Hermesstraße (Nr. 1-77 sowie 85-99) befinden sich zudem auch die Siedlungshäuser der [[Friedensstadt]], einer nach dem [[Ersten]] Weltkrieg im Bereich des Lainzer Tiergartens angelegten Wohnsiedlung für Kriegsinvalide, die nach abgewandelten Planungen Adolf Loos entworfen wurde"}, {"kategorie": "", "text": "Durch die Namensgebung hebt die Hermesstraße die historische und kulturelle Bedeutung der Hermesvilla und des Lainzer Tiergartens hervor, die wichtige Symbole der kaiserlichen Geschichte Wiens sind."}]'::jsonb, ''),
  ('friidnsschdodt', 'Friidnsschdodt', '', '', '', '', 'Friedensstadt', '[{"kategorie": "allg.", "text": "\"Wohnsiedlung im 13. Wiener Gemeindebezirk ([[Hietzing]]), die nach dem [[Ersten]] Weltkrieg im Bereich des [[Lainzer]] Tiergartens als Wohnsiedlung für Kriegsinvalide errichtet wurde\""}, {"kategorie": "", "text": "Die Siedlung erstreckt sich entlang der [[Hermesstraße]] auf den Hausnummern 1-77 und 85-99. Das Projekt wurde nach abgewandelten Planungen von Adolf Loos, einem bedeutenden Architekten der Wiener Moderne, entworfen"}, {"kategorie": "", "text": "Am 19. September 1920 hatten siedlungswillige Kriegsversehrte das Gebiet des Lainzer Tiergartens besetzt, was zur Entstehung der Siedlung Friedensstadt führte. Das Bauvorhaben wurde von der \"Gesellschaft der Freunde\" (den Quäkern) unterstützt"}, {"kategorie": "", "text": "Im Jahr 1921 eröffnete die Pädagogin und Sozialreformerin Eugenie Schwarzwald in der Friedensstadt eine Gemeinschafts- und Ausspeisungsküche. Diese Speiseräume, die ebenfalls von Adolf Loos gestaltet wurden, waren die erste ihrer Art in Wien und ein Vorbild für die Schwarzwald''schen Gemeinschaftsküchen, die während dieser Zeit in Wien eine soziale Funktion erfüllten"}, {"kategorie": "", "text": "Das Areal der Friedensstadt wurde aus dem eingefriedeten Lainzer Tiergarten ausgegliedert und ist ein bemerkenswertes Beispiel für den sozialen Wohnbau der Zwischenkriegszeit, der auf die Bedürfnisse von Kriegsversehrten zugeschnitten war."}]'::jsonb, ''),
  ('atzgasduaf', 'Atzgasduaf', '', '', '', '', 'Atzgersdorf', '[{"kategorie": "allg.", "text": "\"Stadtteil im 23. Wiener Gemeindebezirk ([[Liesing]]) und eine der 89 Wiener Katastralgemeinden Wiens\""}, {"kategorie": "", "text": "Ursprünglich ein eigenständiges Gassengruppendorf, wurde Atzgersdorf am 15. Oktober 1938 im Zuge der Eingemeindung nach [[Groß-Wien]] Teil der Stadt. Zuvor war Atzgersdorf seit 1850 eine eigenständige niederösterreichische Gemeinde. Nach dem [[Zweiten]] Weltkrieg wurde Atzgersdorf 1954 endgültig Teil des 23. Bezirks"}, {"kategorie": "", "text": "Die erste urkundliche Erwähnung von Atzgersdorf datiert um 1120/1130, unter dem Namen Azichinstorf oder Aziehinstorf (abgeleitet von einem Eigennamen \"Atzichi\" in Verbindung mit \"-dorf\"). Die [[Atzgersdorfer]] Kirche wurde an der Wende des 13. zum 14. Jahrhundert gegründet und bildete das Zentrum des Dorfes, dessen Wurzeln bis ins 9. Jahrhundert zurückreichen"}, {"kategorie": "", "text": "Im 19. Jahrhundert erlebte Atzgersdorf durch die Industrialisierung, insbesondere durch die Umwandlung der mittelalterlichen Mühlen in Fabriken, eine wirtschaftliche Blütezeit"}, {"kategorie": "", "text": "Die heutige Katastralgemeinde Atzgersdorf nimmt eine Fläche von etwa 376 Hektar ein. Bis 2010 gehörte auch ein 35 Hektar großes Gebiet im Bezirk [[Meidling]], auf dem der südliche Teil des [[Südwestfriedhofs]] liegt, der Katastralgemeinde Atzgersdorf an. Durch eine Verwaltungsvereinfachung wurde die Katastralgemeindegrenze zur Bezirksgrenze hin verschoben, und dieses Gebiet an die Katastralgemeinde [[Hetzendorf]] übertragen"}, {"kategorie": "", "text": "Atzgersdorf liegt beiderseits des [[Liesingbaches]]. Flussaufwärts befindet sich der gleichnamige Wiener Bezirksteil [[Liesing]], flussabwärts schließen die Wiener Bezirksteile [[Erlaa]] und [[Inzersdorf]] an"}, {"kategorie": "", "text": "Nördlich von Atzgersdorf liegen der Hietzinger Bezirksteil [[Rosenberg]] und die Meidlinger Bezirksteile [[Hetzendorf]] und [[Altmannsdorf]]"}, {"kategorie": "", "text": "Im Ort mündete der aus Mauer kommende [[Knotzenbach]] in die Liesing. Dieser fließt heute großteils unterirdisch und ist daher nur mehr in der Nähe seiner Quelle, beim [[Maurer]] Wald, sichtbar"}, {"kategorie": "", "text": "Heute ist Atzgersdorf ein lebendiger Teil von Liesing und ein beliebter Wohnort. Seit 1988 findet dort jährlich das Atzgersdorfer Oktoberfest statt, das das kulturelle Leben der Region bereichert."}]'::jsonb, ''),
  ('rosnbeag', 'Rosnbeag', '', '', '', '', 'Rosenberg', '[{"kategorie": "allg.", "text": "\"eine der 89 Wiener Katastralgemeinden am [[Rosenhügel]] im 13. Wiener Gemeindebezirk ([[Hietzing]]), welche sich über eine Fläche von nur 40,63 ha erstreckt\""}, {"kategorie": "", "text": "Rosenberg grenzt im Norden an den Hietzinger Bezirksteil [[Speising]], im Süden und Westen an [[Mauer]] und im Osten an [[Atzgersdorf]]. Das Gebiet ist damit an drei Seiten vom 23. Gemeindebezirk ([[Liesing]]) umschlossen"}, {"kategorie": "", "text": "Entstanden ist Rosenberg am 5. Mai 1908 durch die Eingemeindung eines Teils der damals selbstständigen Gemeinde [[Mauer]] nach Wien, der für die Errichtung des von Nathaniel Meyer von Rothschild gestifteten Neurologischen Zentrums der Stadt Wien benötigt wurde. Das 1912 eröffnete Krankenhaus nimmt mit seiner Parkanlage noch heute einen großen Teil der Katastralgemeinde ein"}, {"kategorie": "", "text": "In Rosenberg befindet sich auch der 1873 fertiggestellte Wasserbehälter Rosenhügel der ersten Wiener Hochquellenwasserleitung"}, {"kategorie": "", "text": "Die Bezeichnung Rosenberg leitet sich von einem historischen Flurnamen ab und ist namensgebend auch für die Straße \"Am Rosenberg\", das Pensionistenheim \"Haus Rosenberg\" sowie die Kleingartenanlage \"Rosenberg\""}, {"kategorie": "", "text": "Die Errichtung von Wohnhäusern und damit eine ständige Besiedlung von Rosenberg erfolgte erst relativ spät. In den 1960er Jahren wurde entlang des Wegs Am Rosenberg eine Wohnanlage mit [[Gemeindebauten]] errichtet."}]'::jsonb, ''),
  ('rosnhuegl', 'Rosnhügl', '', '', '', '', 'Rosenhügel', '[{"kategorie": "allg.", "text": "\"markante Anhöhe im Südwesten Wiens, die sich über die Bezirke [[Hietzing]] (13. Bezirk), [[Meidling]] (12. Bezirk) und [[Liesing]] (23. Bezirk) erstreckt\""}, {"kategorie": "", "text": "Ursprünglich wurde hier eine Rosenkultur betrieben, die dem Hügel seinen Namen gab"}, {"kategorie": "", "text": "Der Hügel hat historische Bedeutung in verschiedenen Bereichen, darunter die Wasserversorgung: Hier befindet sich der Wasserbehälter Rosenhügel, der zwischen 1870 und 1873 erbaut wurde und die I. Wiener Hochquellenwasserleitung abschließt. Auch die Rosenhügel-Filmstudios, die von 1919 bis 1923 errichtet wurden, haben filmgeschichtliche Bedeutung als einst modernste Studios Österreichs. Auf deren Gelände entstanden in den letzten Jahren Eigentumswohnungen und ein Kindergarten"}, {"kategorie": "", "text": "Am Rosenhügel befinden sich mehrere bedeutende Gesundheitseinrichtungen, darunter das Neurologische Krankenhaus Rosenhügel und das Orthopädische Spital Speising. Außerdem beherbergt der Hügel das [[Hietzinger]] Bad, Schulen und die Kleingartenanlagen [[Rosenberg]] und Rosenhügel"}, {"kategorie": "", "text": "Am Osthang des Rosenhügels von der Tullnertalgasse über die [[Atzgersdorfer]] Straße Richtung [[Südwestfriedhof]] verläuft unterirdisch die Trasse einer ehemaligen römischen Wasserleitung zum Legionslager Vindobona. Mehrere Stücke dieser Leitung wurden gefunden und archäologisch untersucht"}, {"kategorie": "", "text": "Der Rosenhügel ist bekannt sowohl für seine Villen als auch für seine Gemeindebauten und genossenschaftliche Siedlungen, wie die Siedlung Rosenhügel, die in den 1920er Jahren nach Plänen von Emil Krause und Hugo Mayer errichtet wurde ("}]'::jsonb, ''),
  ('rosnhueglschdrossn', 'Rosnhüglschdrossn', '', '', '', '', 'Rosenhügelstraße', '[{"kategorie": "allg.", "text": "\"Straße im 12., 13. und 23. Wiener Gemeindebezirk ([[Meidling]], [[Hietzing]] und [[Liesing]]), welche die Stadtteile [[Hetzendorf]], [[Speising]], [[Atzgersdorf]] und [[Mauer]] miteinander verbindet\""}, {"kategorie": "", "text": "Die Straße erhielt ihren Namen im Jahr 1892 und ist nach einem historischen Flurnamen (\"Rosenhügel\") benannt. Ursprünglich wurde hier eine Rosenkultur betrieben, die dem Hügel seinen Namen gab"}, {"kategorie": "", "text": "Die Rosenhügelstraße verbindet die verschiedenen Siedlungsgebiete entlang des Hügels und führt durch eine Mischung aus Wohnanlagen, Kleingärten und Villengebieten. Sie spielt eine wichtige Rolle in der Erschließung des Gebiets und bildet eine zentrale Verkehrsachse in diesem Teil von Wien;  4.In der Nähe befinden sich der Wasserbehälter Rosenhügel, der zwischen 1870 und 1873 erbaut wurde und die I. Wiener Hochquellenwasserleitung abschließt, sowie die Rosenhügel-Filmstudios, die von 1919 bis 1923 errichtet wurden, und mehrere bedeutende Gesundheitseinrichtungen, darunter das Neurologische Krankenhaus Rosenhügel und das Orthopädische Spital Speising"}, {"kategorie": "", "text": "Am Osthang des Rosenhügels von der Tullnertalgasse über die [[Atzgersdorfer]] Straße Richtung [[Südwestfriedhof]] verläuft unterirdisch die Trasse einer ehemaligen römischen Wasserleitung zum Legionslager Vindobona. Mehrere Stücke dieser Leitung wurden gefunden und archäologisch untersucht"}, {"kategorie": "", "text": "Der Rosenhügel ist bekannt sowohl für seine Villen als auch für seine Gemeindebauten und genossenschaftliche Siedlungen, wie die Siedlung Rosenhügel, die in den 1920er Jahren nach Plänen von Emil Krause und Hugo Mayer errichtet wurde"}]'::jsonb, ''),
  ('knotznboch', 'Knotznboch', '', '', '', '', 'Knotzenbach', '[{"kategorie": "allg.", "text": "\"kleiner Bach im 23. Wiener Gemeindebezirk ([[Liesing]]), der teils als offenes Gewässer verlief und in den [[Liesingbach]] mündet\""}, {"kategorie": "", "text": "Auf seinem Weg kreuzte er mehrfach Straßen, darunter die [[Endresstraße]] (früher Hauptstraße) und die [[Breitenfurter]] Straße"}, {"kategorie": "", "text": "Der Knotzenbach war in einem schlechten Zustand, da die Abdeckungen, die oft von den Grundeigentümern aus unterschiedlichen Materialien wie Ziegeln, Steinen oder Holz errichtet wurden, unzureichend waren. Dies führte häufig zu Überflutungen"}, {"kategorie": "", "text": "Deshalb beschloss die Stadt Wien 1949, den Bach vollständig zu kanalisieren und zu überdachen (einzuwölben). Gleichzeitig wurde das Schmutzwasserkanalnetz in diesem Gebiet modernisiert"}, {"kategorie": "", "text": "Die Einwölbung des Knotzenbachs erstreckt sich über eine Länge von 3164 Metern und wurde nach neun Jahren Bauzeit 1957 abgeschlossen. Der Kanal verläuft durch die [[Breitenfurter]] Straße, die [[Levasseurgasse]] (früher untere Bahnstraße), die [[Endresstraße]], die [[Lange]] Gasse und die Waldgasse. Verschiedene technische Profile, wie Steinzeugrohre und Maul- und Eiprofile, wurden zur Schmutzwasserableitung verwendet, und zur Sicherung der Sohle wurden Granitsteine und Betonsohlenschalen eingesetzt"}, {"kategorie": "", "text": "Die Baukosten beliefen sich auf 9,293.475 Schilling, und das Kanalprojekt ermöglichte eine verbesserte Wasserableitung und Hochwasserschutz im betroffenen Gebiet."}]'::jsonb, ''),
  ('endresschdrossn', 'Endresschdrossn', '', '', '', '', 'Endresstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 23. Wiener Gemeindebezirk ([[Liesing]]), welche die Stadtteile [[Mauer]] und [[Atzgersdorf]] miteinander verbindet\""}, {"kategorie": "", "text": "Sie wurde am 23. Februar 1966 nach dem Historiker Robert Endres benannt, der von 1892 bis 1964 lebte"}, {"kategorie": "", "text": "Endres veröffentlichte zahlreiche wissenschaftliche Werke zur antiken, österreichischen und europäischen Geschichte. Zu seinen bekanntesten Werken zählen das \"Handbuch der österreichischen Staats- und Wirtschaftsgeschichte\" (1922), \"Geschichte Europas im 19. Jahrhundert\" (1928) und die fünf Bände umfassende \"Geschichte Europas und des Orients\" (1951–1956). Er wurde für seine Verdienste mehrfach geehrt"}, {"kategorie": "", "text": "Heute verläuft die Endresstraße durch ein vorwiegend wohngeprägtes Gebiet, das durch eine Mischung aus Ein- und Mehrfamilienhäusern sowie Wohnanlagen geprägt ist."}]'::jsonb, ''),
  ('levassoeagossn', 'Levassöagossn', '', '', '', '', 'Levasseurgasse', '[{"kategorie": "allg.", "text": "\"Straße im  im 23. Wiener Gemeindebezirk ([[Liesing]]), genauer im Stadtteil [[Atzgersdorf]]\""}, {"kategorie": "", "text": "Die Namensgebung erfolgte zu Ehren des österreichischen Ingenieurs und Pioniers der Stenographie Dipl.-Ing. Dr. Karl Levasseur (1903–1961)"}, {"kategorie": "", "text": "Levasseur war eine herausragende Persönlichkeit in der Entwicklung der Stenographie in Österreich und hatte sich insbesondere als Wissenschaftler und Innovator auf diesem Gebiet verdient gemacht"}, {"kategorie": "", "text": "Die Levasseurgasse ist heute hauptsächlich von Wohnhäusern und kleinen Mehrfamilienhäusern geprägt. Die Umgebung ist eher ruhig und typisch für den Vorstadtcharakter von Liesing."}]'::jsonb, ''),
  ('sagedagossn', 'Sagedagossn', '', '', '', '', 'Sagedergasse', '[{"kategorie": "allg.", "text": "\"Verbindungsstraße im 12. Wiener Gemeindebezirk ([[Meidling]]), genauer im Stadtteil [[Altmannsdorf]]\""}, {"kategorie": "", "text": "Sie wurde im Jahr 1892 nach der Wohltäterin Anna Sageder (1818–1873) benannt"}, {"kategorie": "", "text": "Anna Sageder lebte in Altmannsdorf und fand dort große Anerkennung durch ihre sozialen und karitativen Taten. Sie war mit Johann Sageder, dem Besitzer des herrschaftlichen Gutes Altmannsdorf und der größten Meierei Wiens, verheiratet"}, {"kategorie": "", "text": "Sie gründete die Sagedersche Stiftung, die in der Region eine wichtige Rolle bei der Unterstützung von Bedürftigen spielte. Einer ihrer wichtigsten Beiträge war die Renovierung der St.-Anna-Kapelle am [[Schöpfwerk]] im Jahr 1855, die sie vollständig finanzierte. Diese Kapelle war ein bedeutendes religiöses Zentrum für die Gemeinde Altmannsdorf, und durch ihre Spende konnte sie umfassend renoviert und in ihrem Bestehen gesichert werden"}, {"kategorie": "", "text": "In Anerkennung ihrer großzügigen Unterstützung wurde die Kapelle seither auch als Sageder-Kapelle bekannt, was ihren Einfluss auf das Gemeindeleben und ihre Verbundenheit mit der religiösen Tradition des Ortes widerspiegelt. Die Kapelle bleibt bis heute ein symbolischer Ort, der an Anna Sageder und ihr Erbe als Wohltäterin erinnert"}, {"kategorie": "", "text": "Die Sagedergasse ist eine wichtige Verkehrsader in [[Altmannsdorf]]. Sie verbindet Wohngebiete und Gewerbezonen und ist stark frequentiert"}, {"kategorie": "", "text": "Sie ist verkehrstechnisch gut angebunden und liegt in der Nähe der A23, auch als [[Südosttangente]] Wien bekannt, die eine der wichtigsten Autobahnen für den Stadtverkehr in Wien darstellt."}]'::jsonb, ''),
  ('rodaun', 'Rodaun', '', '', '', '', 'Rodaun', '[{"kategorie": "allg.", "text": "\"Stadtteil im 23. Wiener Gemeindebezirk ([[Liesing]]) sowie eine der 89 Wiener Katastralgemeinden\""}, {"kategorie": "", "text": "Mit einer Fläche von 214,45 Hektar ist Rodaun flächenmäßig die kleinste Katastralgemeinde in Liesing und liegt am Übergang des [[Liesingbachs]] vom [[Wienerwald]] ins [[Wiener]] Becken auf einer Seehöhe von 240 Metern. Rodaun grenzt an die Bezirksteile [[Kalksburg]] und [[Mauer]], sowie an die niederösterreichischen Gemeinden Perchtoldsdorf und Kaltenleutgeben"}, {"kategorie": "", "text": "Der Name Rodaun wird erstmals um 1170 als „Radune“ urkundlich erwähnt (\"Radune\" = Mädchenname slawischen Ursprungs). Die Gegend war in der Vergangenheit Sitz der Herren von Rodaun, einem babenbergischen Dienstmannengeschlecht"}, {"kategorie": "", "text": "Im Mittelalter war die Ortschaft Schauplatz wiederholter Zerstörungen, unter anderem während der [[Türkenbelagerungen]] 1529 und 1683, und entwickelte sich im 18. Jahrhundert zu einem beliebten Ort für den Wiener Adel, insbesondere aufgrund seiner Schwefel- und Eisenquellen"}, {"kategorie": "", "text": "Zu den markanten Bauwerken zählt das [[Schloss]] Rodaun, dessen Ursprünge auf die Zeit der [[Babenberger]] zurückgehen, sowie die [[Bergkirche]] Rodaun, erbaut 1738. Zudem war der Dichter Hugo von Hofmannsthal zeitweise Bewohner Rodauns, im sogenannten [[Hofmannsthal-Schlössl]]"}, {"kategorie": "", "text": "Rodaun ist heute ein beliebter Wohnort mit bedeutender geologischer Struktur. Es ist Teil des Biosphärenparks [[Wienerwald]] und umfasst Teile des Landschaftsschutzgebiets Liesing, einschließlich des Eichkogel-Rückens, auf dem sich der höchste Punkt Liesings, der [[Eichkogel]] (428 m), befindet.  Gesondert als Naturdenkmal ausgewiesen ist unter anderem die [[Mizzi-Langer-Wand]] am Zugberg"}, {"kategorie": "", "text": "Ferner befinden sich in Rodaun auch mehrere [[Gemeindebauten]], von denen die bedeutendste die Wohnhausanlage an der [[Breitenfurter]] Straße 401–413 ist. Dieses Bauwerk, das als herausragendes Beispiel der Postmoderne gilt, steht unter Denkmalschutz."}]'::jsonb, ''),
  ('schdichkoppngwoelb', 'Schdichkoppngwölb', '', '', '', '', 'Stichkappengewölbe', '[{"kategorie": "allg.", "text": "\"spezielle Gewölbeform, bei der sich seitliche Teilgewölbe, sogenannte [[Stichkappen]], in ein Hauptgewölbe (meist ein [[Tonnengewölbe]]) einschneiden\""}, {"kategorie": "", "text": "Diese Stichkappen sind kleinere, halbkreisförmige oder segmentartige Auswölbungen, die in der Regel zu Fenstern oder Durchgängen führen und die Decke durchbrechen"}, {"kategorie": "", "text": "Stichkappengewölbe werden oft verwendet, um Fenster oder Nischen in Tonnengewölben unterzubringen, und ermöglichen eine bessere Belichtung oder den Einbau von Türen und Durchgängen"}, {"kategorie": "", "text": "Sie sind ein typisches Merkmal vieler Bauwerke der [[Renaissance]] und des [[Barocks]], insbesondere in Kirchen oder Palästen"}, {"kategorie": "", "text": "Ein typisches Beispiel für ein Stichkappengewölbe findet sich u.a. im [[Hofmannsthal-Schlössl]]."}]'::jsonb, ''),
  ('eichkogl', 'Eichkogl', '', '', '', '', 'Eichkogel', '[{"kategorie": "allg.", "text": "\"428 Meter hoher Berg im äußersten Südwesten von Wien im 23. Bezirk ([[Liesing]]), genauer im Stadtteil [[Rodaun]]\""}, {"kategorie": "", "text": "Er ist der höchste Berg des Bezirks und wird von drei Seiten von Niederösterreich umschlossen. Der Berg liegt im [[Wienerwald]] und gehört geologisch zu den Nördlichen Kalkalpen"}, {"kategorie": "", "text": "Der Eichkogel ist bekannt für seine vielfältige Vegetation und die speziellen klimatischen Bedingungen, die eine Mischung aus Trockenrasen, Wäldern und Steppen begünstigen. Die klimatische Übergangslage, in der sowohl pannonische als auch atlantische Einflüsse zusammenkommen, schafft ideale Bedingungen für zahlreiche seltene Pflanzen- und Tierarten, die in Österreich gefährdet sind. Dies macht den Berg zu einem wichtigen Standort für den Naturschutz und die Artenvielfalt"}, {"kategorie": "", "text": "Historisch gesehen wurde der Eichkogel seit 1158/1182 als Wartberg genutzt und diente als Aussichtspunkt und für Rauchsignale. Während des [[Zweiten]] Weltkriegs wurde er als Standort für eine Flakstellung verwendet"}, {"kategorie": "", "text": "Heute ist der Eichkogel ein Naturschutzgebiet, das seit 1960 schrittweise unter Schutz gestellt wurde, um seine einzigartige Landschaft und Artenvielfalt zu bewahren."}]'::jsonb, ''),
  ('babnbeaga', 'Babnbeaga', '', '', '', '', 'Babenberger', '[{"kategorie": "allg.", "text": "\"bedeutendes österreichisches Herrschergeschlecht, das vom 10. bis zum 13. Jahrhundert regierte\""}, {"kategorie": "", "text": "Die Babenberger stammten ursprünglich aus dem fränkischen Raum und wurden im Jahr 976 mit der Markgrafschaft Ostarrichi (dem späteren Österreich) belehnt. Unter den Babenbergern entwickelte sich dieses Gebiet von einer Grenzmark des [[Heiligen]] Römischen Reichs zu einem eigenständigen Herzogtum, das die Grundlage für das spätere Österreich bildete"}, {"kategorie": "", "text": "Bekannte Herrscher aus der Dynastie sind unter anderem: (i) [[Leopold]] III. (der Heilige), der als Schutzpatron Österreichs gilt und 1485 heiliggesprochen wurde, (ii) [[Heinrich]] II. Jasomirgott, der Österreich 1156 zum Herzogtum erhob, sowie (iii) Leopold V., der durch die Einnahme von Richard Löwenherz während des Dritten Kreuzzugs zu Reichtum und Macht gelangte"}, {"kategorie": "", "text": "Die Herrschaft der Babenberger endete 1246 mit dem Tod von [[Herzog]] Friedrich II., der ohne männliche Nachkommen starb, was zu einem Machtvakuum und schließlich zur Übernahme durch die [[Habsburger]] führte"}, {"kategorie": "", "text": "Die Babenberger spielten eine entscheidende Rolle in der Geschichte Österreichs und legten den Grundstein für das spätere [[Habsburgerreich]]."}]'::jsonb, ''),
  ('ealaa', 'Ealaa', '', '', '', '', 'Erlaa', '[{"kategorie": "allg.", "text": "\"Stadtteil Wiens im 23. Wiener Gemeindebezirk ([[Liesing]]) sowie eine der 89 Wiener Katastralgemeinden\""}, {"kategorie": "", "text": "Der Ort besteht aus den beiden Teilen [[Alt-Erlaa]] und [[Neu-Erlaa]] und wurde erstmals 1114 als „Erila“ urkundlich erwähnt. Der Name leitet sich vermutlich von einem Erlengehölz ab. Erlaa entwickelte sich langsam und war lange von Landwirtschaft geprägt"}, {"kategorie": "", "text": "Im 18. Jahrhundert erwarb Fürst Georg Adam von Starhemberg die Grundherrschaft und ließ das barocke [[Schloss]] Alterlaa errichten. Mit der Industrialisierung und der Entstehung von [[Neu-Erlaa]] Mitte des 19. Jahrhunderts wuchs die Bevölkerung stark an, und der Ort erlebte einen Wandel von einem landwirtschaftlich geprägten Dorf zu einem verstädterten Bezirksteil"}, {"kategorie": "", "text": "1938 wurde Erlaa im Zuge des \"Anschlusses\" Österreichs an das Deutsche Reich nach Wien eingemeindet"}, {"kategorie": "", "text": "[[Alt-Erlaa]] liegt nahe [[Atzgersdorf]], während [[Neu-Erlaa]] in Richtung der [[Triester]] Straße im Südosten liegt"}, {"kategorie": "", "text": "Zu den bekanntesten Bauwerken in Erlaa gehören das [[Schloss]] Alterlaa und der [[Wohnpark]] Alt-Erlaa, der zwischen 1973 und 1985 errichtet wurde und durch seine markante Architektur berühmt ist"}, {"kategorie": "", "text": "Heute leben etwa 15.000 Menschen in Erlaa, das durch seine Wohngebiete, Parks wie den [[Schlosspark]] Alterlaa und den [[Michael-Bausback-Park]], sowie durch die fast 500 Meter lange [[Rosskastanien-Allee]] (Naturdenkmal zwischen dem Schloss und dem Fluss [[Liesing]]) geprägt ist"}, {"kategorie": "", "text": "Ein Erlenblatt auf blauem Untergrund symbolisiert Erlaa im Wappen des Bezirks [[Liesing]]."}]'::jsonb, ''),
  ('kreizgraadgwoelb', 'Kreizgraadgwölb', '', '', '', '', 'Kreuzgratgewölbe', '[{"kategorie": "allg.", "text": "\"Gewölbeform, die durch die Kreuzung von zwei [[Tonnengewölben]] entsteht, die sich rechtwinklig schneiden\""}, {"kategorie": "", "text": "An den Schnittlinien der Gewölbeflächen entstehen die sogenannten Grate, die das charakteristische Kreuzmuster im Grundriss bilden"}, {"kategorie": "", "text": "Diese Grate sind die tragenden Elemente des Gewölbes, während die Flächen zwischen den Graten leicht gewölbt sind"}, {"kategorie": "", "text": "Das Kreuzgratgewölbe wurde in der Romanik häufig verwendet, da es eine stabile und wirtschaftliche Methode war, größere Räume zu überspannen. Es war eine Weiterentwicklung des [[Tonnengewölbes]] und ermöglichte größere Spannweiten bei gleichzeitiger Entlastung der tragenden Wände"}, {"kategorie": "", "text": "Beispiele von Bauwerken mit Kreuzgratgewölben in Wien sind u.a. der romanische Teil des [[Stephansdoms]] sowie das [[Schloss]] Alt-Erlaa."}]'::jsonb, ''),
  ('gregorygossn', 'Gregorygossn', '', '', '', '', 'Gregorygasse', '[{"kategorie": "allg.", "text": "\"historisch bedeutsame Straße im 23. Wiener Gemeindebezirk ([[Liesing]]), genauer im Stadtteil [[Alt-Erlaa]]\""}, {"kategorie": "", "text": "Die Straße, welche die [[Erlaaer]] Straße mit der [[Breitenfurter]] Straße verbindet, wurde am 3. Februar 1954 nach Leopold Gregory benannt, der von 1885 bis 1903 Bürgermeister von Erlaa wa"}, {"kategorie": "", "text": "Während seiner Amtszeit setzte sich Gregory für die Entwicklung und Modernisierung der damals eigenständigen Ortsgemeinde [[Erlaa]] ein. Seine Verdienste um den Ort, insbesondere im Bereich der Infrastruktur und öffentlichen Dienste, führten dazu, dass ihm zu Ehren diese wichtige Straße benannt wurde"}, {"kategorie": "", "text": "Die Gregorygasse verläuft nahe dem [[Schloss]] Alterlaa und ist bekannt für die [[Rosskastanienallee]], die unter Naturschutz steht. Diese Allee ist ein Naturdenkmal von [[Alt-Erlaa]], und wurde ursprünglich als prunkvoller Zugang zum [[Schloss]] Alt-Erlaa angelegt. Sie verläuft parallel zur Gasse und ist in Richtung des kaiserlichen Schlosses [[Schönbrunn]] ausgerichtet"}, {"kategorie": "", "text": "Die Gregorygasse verbindet somit die historische Bedeutung des Schlosses Alterlaa und der alten Herrschaftsgüter mit den modernen Wohn- und Verkehrsstrukturen des Bezirks."}]'::jsonb, ''),
  ('inzasduaf', 'Inzasduaf', '', '', '', '', 'Inzersdorf', '[{"kategorie": "allg.", "text": "\"Stadtteil Wiens im 23. Wiener Gemeindebezirk ([[Liesing]]) sowie eine der 89 Wiener Katastralgemeinden\""}, {"kategorie": "", "text": "Die erste urkundliche Erwähnung von Inzersdorf stammt aus dem 12. Jahrhundert (um 1120/1130). Der Name des Ortes leitet sich wahrscheinlich vom Personennamen Imizi, dem vermutlichen Dorfgründer, ab"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte entwickelte sich Inzersdorf zu einem wichtigen landwirtschaftlichen und später industriellen Zentrum, insbesondere durch die reichen Tonschichten des Wienerbergs, die den Ziegelwerken der Region als Rohstoff dienten"}, {"kategorie": "", "text": "Historisch bestand Inzersdorf aus zwei Teilen: dem ursprünglichen Dorf und dem nördlichen Gebiet, das 1890 als Inzersdorf-Stadt in den 10. Wiener Bezirk ([[Favoriten]]) eingemeindet wurde. Der südliche Teil verblieb bis 1938 als eigenständige Gemeinde und wurde dann zusammen mit anderen Ortschaften dem neu geschaffenen 25. Bezirk (heute der 23. Bezirk, [[Liesing]]) angeschlossen"}, {"kategorie": "", "text": "Inzersdorf war in seiner Blütezeit für seine Ziegelindustrie bekannt, die im 19. Jahrhundert unter der Familie Drasche florierte. Auch bedeutende Industriebetriebe siedelten sich im Laufe der Zeit in Inzersdorf an. Im Zuge des Zweiten Weltkriegs wurden zahlreiche Gebäude zerstört, darunter das Schloss Inzersdorf, ein barockes Wasserschloss, das später abgerissen wurde"}, {"kategorie": "", "text": "Heute ist Inzersdorf der flächenmäßig größte Teil von [[Liesing]], geprägt von Wohnsiedlungen, Industriegebieten und öffentlichen Einrichtungen wie dem [[Großgrünmarkt]]"}, {"kategorie": "", "text": "Kulturell ist der Stadtteil durch die [[Pfarrkirche]] Inzersdorf, das [[Maria-Theresien-Schlössl]], das [[Grünberger]] Schlössl und den [[Draschepark]] bekannt"}, {"kategorie": "", "text": "Mit seiner langen Geschichte, die sowohl landwirtschaftliche als auch industrielle Phasen umfasst, bleibt Inzersdorf ein wichtiger Teil des südlichen Wiens."}]'::jsonb, ''),
  ('phorushoin', 'Phorushoin', '', '', '', '', 'Phorushalle', '[{"kategorie": "allg.", "text": "\"ehemalige Markthalle am nicht mehr bestehenden [[Phorusplatz]] in den Wiener Bezirken [[Wieden]] (4. Bezirk) und [[Margareten]] (5. Bezirk)\""}, {"kategorie": "", "text": "Die Phorushalle wurde 1880 nach Plänen des Architekten Friedrich Paul errichtet, als Teil eines Gemeinderatsbeschlusses zum Bau von vier Markthallen in Wien"}, {"kategorie": "", "text": "Die Phorushalle diente zunächst als Detailmarkthalle und wurde 1952 in eine Großmarkthalle für Blumen umgewandelt"}, {"kategorie": "", "text": "Nach der Eröffnung der neuen Blumenhalle im [[Großmarkt]] Wien im Jahr 1969 wurde die Phorushalle stillgelegt und stand bis 1979 leer"}, {"kategorie": "", "text": "Im Oktober 1979 wurde sie von Jugendlichen besetzt, die ein selbstverwaltetes Kommunikationszentrum forderten"}, {"kategorie": "", "text": "Nach einem Polizeieinsatz am 21. Oktober wurde die Halle einen Tag später, am 22. Oktober 1979, abgerissen. Heute steht an ihrer Stelle ein Pensionistenheim."}]'::jsonb, ''),
  ('phorusplotz', 'Phorusplotz', '', '', '', '', 'Phorusplatz', '[{"kategorie": "allg.", "text": "\"einst bedeutender Platz im 4. Wiener Gemeindebezirk ([[Wieden]]), der am 11. März 1881 nach der Firma \"Phorus\" benannt wurde\""}, {"kategorie": "", "text": "Diese Aktiengesellschaft, gegründet im Jahr 1824 in Margareten, spezialisierte sich auf die maschinelle Zerkleinerung von Brennholz mittels Dampfsägen. Die Gründung erfolgte durch sechs prominente Wiener Financiers, darunter Ferdinand Graf Pálffy und Franz Unger, wobei sich der Name \"Phorus\" aus den Anfangsbuchstaben ihrer Namen zusammensetzte"}, {"kategorie": "", "text": "Die Gesellschaft spielte eine wichtige Rolle bei der Modernisierung der Brennholzversorgung in Wien, indem sie das Brennholz mit eigenen Zustellwagen direkt an Haushalte lieferte. Aufgrund hoher Betriebskosten stellte sie jedoch in den 1950er Jahren ihren Betrieb ein"}, {"kategorie": "", "text": "Der Phorusplatz war ein lebhafter Ort mit einer Markthalle, die 1880 erbaut wurde und später als Blumengroßmarkthalle diente. Er erstreckte sich von der [[Phorusgasse]] bis zur [[Ziegelofengasse]] und war auf Höhe der [[Leibenfrostgasse]] von der großen Markthalle geprägt, die den Platz beherrschte"}, {"kategorie": "", "text": "Im Jahr 1982 wurde der Phorusplatz im Zuge der Errichtung eines kommunalen Pensionistenheims vollständig umgestaltet. Der Bau der Halle musste dem neuen Bauprojekt weichen, und eine verbleibende Teilfläche des Platzes wurde in die Leibenfrostgasse integriert. So verschwand der historische Phorusplatz aus dem Stadtbild, nachdem er über ein Jahrhundert eine zentrale Rolle im Viertel gespielt hatte."}]'::jsonb, ''),
  ('phorusgossn', 'Phorusgossn', '', '', '', '', 'Phorusgasse', '[{"kategorie": "allg.", "text": "\"historisch bedeutsame Gasse im 4. Wiener Gemeindebezirk ([[Wieden]]) mit einer langjährigen Verbindung zur industriellen Entwicklung des Gebiets\""}, {"kategorie": "", "text": "Sie wurde im Jahr 1871 auf dem Gelände der ehemaligen Firma \"Phorus\" angelegt, einer Aktiengesellschaft, die 1824 gegründet wurde, um das Zerkleinern von Brennholz in Wien zu mechanisieren"}, {"kategorie": "", "text": "Die Gründung erfolgte durch sechs prominente Wiener Financiers, darunter Ferdinand Graf Pálffy und Franz Unger, wobei sich der Name \"Phorus\" aus den Anfangsbuchstaben ihrer Namen zusammensetzte"}, {"kategorie": "", "text": "Die Gesellschaft spielte eine wichtige Rolle bei der Modernisierung der Brennholzversorgung in Wien, indem sie das Brennholz mit eigenen Zustellwagen direkt an Haushalte lieferte. Aufgrund hoher Betriebskosten stellte sie jedoch in den 1950er Jahren ihren Betrieb ein"}, {"kategorie": "", "text": "Im Zuge der Neugestaltung des Gebiets wurde der benachbarte [[Phorusplatz]], der früher von einer Markthalle dominiert wurde, 1982 aufgelassen. Die Phorusgasse wurde durch die Einbeziehung der verbleibenden Verkehrsfläche des ehemaligen Phorusplatzes am 2. September 1982 verlängert"}, {"kategorie": "", "text": "Historisch befanden sich in diesem Bereich auch städtische Ziegelöfen, was zur Benennung der angrenzenden [[Ziegelofengasse]] führte. Diese Ziegelöfen spiegeln die industrielle Vergangenheit des Viertels wider, das sowohl von der Ziegelproduktion als auch von der Holzverarbeitung geprägt war"}, {"kategorie": "", "text": "Die Phorusgasse verbindet heute diesen historischen industriellen Hintergrund mit der modernen urbanen Struktur des Bezirks Wieden. Sie ist ein Teil des städtischen Gedächtnisses und steht symbolisch für die industrielle Entwicklung Wiens im 19. Jahrhundert."}]'::jsonb, ''),
  ('ziiglofngossn', 'Ziiglofngossn', '', '', '', '', 'Ziegelofengasse', '[{"kategorie": "allg.", "text": "\"historisch bedeutsame Gasse im 4. und 5. Wiener Gemeindebezirk ([[Wieden]] und [[Margareten]])\""}, {"kategorie": "", "text": "Die Gasse wurde 1862 nach den hier bereits vor 1683 und bis etwa 1770 existierenden städtischen Ziegelöfen benannt. Diese Ziegelöfen lieferten wichtige Baumaterialien für die Stadt Wien. Ursprünglich war die Ziegelofengasse ein Feldweg, der um 1700 nur zur Stadt hin angebunden war"}, {"kategorie": "", "text": "1862 wurde der südliche Teil der Gasse, der zuvor als Piaristengasse bekannt war, mit der Ziegelofengasse zusammengelegt. Am 2. September 1982 wurde nach der Auflassung des benachbarten [[Phorusplatzes]] eine verbleibende Teilfläche des Platzes in die Ziegelofengasse integriert"}, {"kategorie": "", "text": "Die Gasse zeichnet sich durch ihre historische Bausubstanz aus, darunter eine geschlossene Reihe von Biedermeierhäusern (Nummern 5-13, erbaut 1826-1828) sowie spätbarocke Wohnhäuser, wie etwa die Nummern 21, 27 und 37, die zum Teil aus dem 18. Jahrhundert stammen. Diese Häuser spiegeln die Entwicklung der Gasse von einem industriellen Standort hin zu einem bürgerlichen Wohngebiet wider."}]'::jsonb, ''),
  ('leibnfrostgossn', 'Leibnfrostgossn', '', '', '', '', 'Leibenfrostgasse', '[{"kategorie": "allg.", "text": "\"historisch bedeutsame Gasse im 4. Wiener Gemeindebezirk ([[Wieden]])\""}, {"kategorie": "", "text": "Sie wurde 1875 nach dem Wiener Weingroßhändler und Hofweinlieferanten Franz Leibenfrost benannt"}, {"kategorie": "", "text": "Leibenfrost, geboren am 23. März 1790 in Wien und gestorben am 9. Juli 1851 in Lainz, übernahm 1812 das Gasthaus seines Vaters, das \"Jägerhorn\" in der [[Dorotheergasse]]. Er erwarb sich schnell einen ausgezeichneten Ruf als Weinexperte, und prominente Persönlichkeiten wie der Dichter Franz Grillparzer zählten zu seinen Stammgästen. 1820 eröffnete er ein weiteres Kaffeehaus, das Café Leibenfrost, gegenüber dem \"Silbernen Kaffeehaus\""}, {"kategorie": "", "text": "Leibenfrost wurde 1831 zum kaiserlich-königlichen Hoflieferanten ernannt und übernahm später die Oberaufsicht über den Hofkeller. Neben seiner erfolgreichen beruflichen Tätigkeit war er auch als Philanthrop bekannt. Er half während der [[Donauüberschwemmung]] 1830 und der [[Choleraepidemie]] 1831/32 tatkräftig und unterstützte die Militärspitäler in Wien mit großzügigen Spenden"}, {"kategorie": "", "text": "Am 2. September 1982 wurde die Leibenfrostgasse durch die Einbeziehung einer nach der Auflösung des benachbarten [[Phorusplatzes]] verbleibenden Verkehrsfläche verlängert"}, {"kategorie": "", "text": "Die Gasse erinnert heute nicht nur an die Verdienste Leibenfrosts als Weinhändler und Philanthrop, sondern auch an seine bedeutende Rolle in der Wiener Gesellschaft des 19. Jahrhunderts."}]'::jsonb, ''),
  ('choleraepidemii', 'Choleraepidemii', '', '', '', '', 'Choleraepidemie', '[{"kategorie": "allg.", "text": "\"verheerende Seuche, die Wien im 19. Jahrhundert heimsuchte\""}, {"kategorie": "", "text": "Nachdem [[Pestepidemien]] seit 1713 ausgeblieben waren, glaubte man, durch Maßnahmen wie Quarantäne und Pestkordon vor weiteren Epidemien geschützt zu sein. Doch ab den 1830er Jahren breitete sich die Cholera, eine damals in Europa unbekannte Krankheit, wie eine Naturkatastrophe über den Kontinent aus. Die Krankheit wird durch das Bakterium cholera vibrio übertragen, das sich besonders in stehendem Wasser bei feuchtwarmen Temperaturen entwickelt. Die Infektion erfolgte durch verseuchtes Trinkwasser oder kontaminierte Lebensmittel"}, {"kategorie": "", "text": "Die Cholera nahm ihren Ausgang auf dem indischen Subkontinent und erreichte Wien erstmals im August 1831, wo sie in der Nacht vom 13. auf den 14. September ausbrach. Die Seuche breitete sich rasch aus, da die hygienischen Zustände, insbesondere die fehlende Kanalisation, die Verbreitung über das Grundwasser begünstigten. Die Abwässer flossen in die Flüsse und gelangten in die Hausbrunnen, was die Wasserversorgung in Wien stark belastete"}, {"kategorie": "", "text": "In den folgenden Jahrzehnten suchten wiederholte Cholera-Epidemien die Stadt heim, darunter besonders schwere Ausbrüche in den Jahren 1836, 1849, 1854/55, 1866 und 1873. Zwischen 1831 und 1873 starben rund 18.000 Wiener an der Cholera. Die Epidemien trafen vor allem die ärmeren Schichten der Bevölkerung, die unter schlechten hygienischen Bedingungen lebten"}, {"kategorie": "", "text": "Die Wiener Gesundheitsbehörden reagierten mit Maßnahmen wie der Einrichtung von Notspitälern und der Desinfektion öffentlicher Anlagen. Es wurden neue Wasserversorgungssysteme geschaffen, darunter die Wienflusssammelkanäle und die [[Kaiser-Ferdinands-Wasserleitung]], um die Ausbreitung der Seuche einzudämmen"}, {"kategorie": "", "text": "Erst die Entdeckung des Cholera-Erregers durch Robert Koch in den 1880er Jahren legte die wissenschaftliche Grundlage für eine effektive Bekämpfung der Krankheit."}]'::jsonb, ''),
  ('pestepidemiin', 'Pestepidemiin', '', '', '', '', 'Pestepidemien', '[{"kategorie": "allg.", "text": "\"verheerende Seuchenausbrüche in Wien (insbesondere die Ausbrüche 1679 und 1713), die große Teile der Bevölkerung dahinrafften\""}, {"kategorie": "", "text": "Pestepidemie 1679: Nachdem die Pest zuletzt in den Jahren 1653-1656 Wien heimgesucht hatte, kehrte sie 1679 zurück. Die Seuche gelangte über das Osmanische Reich nach Ungarn und schließlich nach Ostösterreich. Die ersten Fälle traten im Spätherbst 1678 auf, wurden aber als „hitziges Fieber“ missinterpretiert. Erst im Juli 1679, als die Zahl der Toten dramatisch anstieg, erkannte man den Ausbruch der Pest. Ihren Höhepunkt erreichte die Epidemie im September 1679 mit fast 3.000 Todesopfern in einem Monat, und die Zahl der geschätzten Opfer lag bei mindestens 12.000. Chaotische Zustände prägten die Stadt, während Leichen oft tagelang auf den Straßen lagen. Die [[Pestgruben]] wurden in den Vororten angelegt, und Maßnahmen zur Eindämmung der Seuche griffen nur begrenzt. Im kollektiven Gedächtnis der Wiener blieb die Pest tief verankert. Zu Ehren des Überlebens wurde die [[Pestsäule]] am Graben errichtet, und bis ins 18. Jahrhundert fanden Pestprozessionen statt"}, {"kategorie": "", "text": "Pestepidemie 1713: Die letzte große Pestepidemie in Wien brach 1713 aus, als die Seuche erneut aus Ungarn eingeschleppt wurde. Ihren Höhepunkt erreichte sie im Frühjahr und Sommer 1713. Die genaue Zahl der Opfer bleibt unklar, wird jedoch auf rund 2.000-2.500 geschätzt. Um die Seuche einzudämmen, wurden Pestlazarette eingerichtet, Messen durften nur noch unter freiem Himmel stattfinden, und es wurden strenge Kontrollen am [[Linienwall]] durchgeführt. Unruhen wie 1679 blieben aus, doch der Zugang zum Hof wurde streng kontrolliert. Zum Gedenken an das Ende der Pest ließ Kaiser [[Karl]] VI. die [[Karlskirche]] erbauen, die dem Pestheiligen Karl Borromäus geweiht wurde. Diese Kirche gilt als eines der markantesten Bauwerke Wiens, das an die Überwindung der Seuche erinnert."}]'::jsonb, ''),
  ('pestgruabm', 'Pestgruabm', '', '', '', '', 'Pestgruben', '[{"kategorie": "allg.", "text": "\"Massengräber, die während der [[Pestepidemien]] angelegt wurden, um die große Anzahl der an der Pest verstorbenen Menschen schnell und hygienisch zu bestatten\""}, {"kategorie": "", "text": "Da die Zahl der Toten oft so hoch war, dass herkömmliche Bestattungsmethoden nicht ausreichten, wurden diese Gruben meist außerhalb der Stadtmauern oder in den Vororten angelegt"}, {"kategorie": "", "text": "Während der Pestepidemie von 1679 in Wien wurden die Leichen mit ungelöschtem Kalk bedeckt, um die Verbreitung der Seuche zu verhindern"}, {"kategorie": "", "text": "Trotz eines offiziellen Verbots wurden auch in der Nähe von Kirchen wie dem [[Stephansdom]] Pestopfer beerdigt"}, {"kategorie": "", "text": "Pestgruben spielten eine zentrale Rolle in den Maßnahmen zur Seucheneindämmung und blieben im kollektiven Gedächtnis vieler europäischer Städte als symbolträchtige Orte des Massensterbens in Erinnerung."}]'::jsonb, ''),
  ('donauiwaschwemmungan', 'Donauiwaschwemmungan', '', '', '', '', 'Donauüberschwemmungen', '[{"kategorie": "allg.", "text": "\"häufige Naturkatastrophen in der Geschichte Wiens, die besonders bis zur [[Donauregulierung]] im 19. Jahrhundert eine große Bedrohung darstellten\""}, {"kategorie": "", "text": "Die Stadt Wien liegt an der Donau, die bei starkem Regen und Schneeschmelze regelmäßig über die Ufer trat und weite Teile der Stadt und der umliegenden Gebiete überschwemmte"}, {"kategorie": "", "text": "Die Donauüberschwemmung von 1830 war eine der verheerendsten. Sie überflutete große Teile der Wiener Vororte und führte zu erheblichen Schäden und Verlusten an Menschenleben. Die Bevölkerung, insbesondere in ärmeren Gegenden, litt stark unter den Auswirkungen, da viele Häuser zerstört wurden. Auch die Infrastruktur und die Nahrungsmittelversorgung waren betroffen"}, {"kategorie": "", "text": "Diese Überschwemmungen brachten wiederholt wirtschaftliche Schäden und humanitäre Krisen mit sich, was die Stadt dazu veranlasste, nach dauerhaften Lösungen zu suchen. Dies führte schließlich zur [[Donauregulierung]], die zwischen 1870 und 1875 umgesetzt wurde. Dabei wurde das Flussbett der Donau begradigt und der [[Donaukanal]] sowie das Inundationsgebiet geschaffen, um die Auswirkungen von Hochwasser zu kontrollieren und künftige Überschwemmungen zu verhindern"}, {"kategorie": "", "text": "Diese Maßnahmen haben das Risiko von Donauüberschwemmungen in Wien erheblich reduziert und die Stadt vor ähnlichen Katastrophen wie 1830 bewahrt."}]'::jsonb, ''),
  ('blumantoi', 'Blumantoi', '', '', '', '', 'Blumental', '[{"kategorie": "allg.", "text": "\"Nebental des Liesingtals im Osten des 23. Wiener Gemeindebezirks ([[Liesing]]), im Stadtteil [[Inzersdorf]], südlich des [[Liesingbachs]] gelegen\""}, {"kategorie": "", "text": "Das Blumental markiert dort, wo es in das Liesingtal einmündet, den tiefsten Punkt des Bezirks (178 Meter Seehöhe). Nach Südwesten hin steigt das Tal bis zur [[Laxenburger]] Straße auf 186 Meter an. Das Blumental umfasst im weiteren Sinne auch den Nordhang des [[Wienerbergs]] und setzt sich im [[Reifental]] fort, das den Wienerberg vom [[Laaer]] Berg trennt"}, {"kategorie": "", "text": "Historisch war das Blumental bis Mitte des 20. Jahrhunderts ein weitgehend unverbautes Wiesengebiet, mit Ausnahme des Bahnhofs Blumental der Pottendorfer Linie, der 1874 eröffnet wurde"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg begann die Bebauung entlang der [[Laxenburger]] Straße, und es entstanden Siedlungen sowie Industrie- und Gewerbebauten. Ein bedeutender Bau war die biologische Kläranlage Blumental, die 1969 errichtet wurde und bis 1996 in Betrieb war. Heute dienen ihre Behälter als Hochwasserspeicher"}, {"kategorie": "", "text": "Das Gebiet beherbergt zudem den [[Großmarkt]] Wien, der 1972 eröffnet wurde, sowie den [[Islamischen]] Friedhof Wien, der 2008 im Westen des Blumentals entstand."}]'::jsonb, ''),
  ('reifntoi', 'Reifntoi', '', '', '', '', 'Reifental', '[{"kategorie": "allg.", "text": "\"kleines Tal im Süden Wiens, das den [[Wienerberg]] vom [[Laaer]] Berg trennt\""}, {"kategorie": "", "text": "Es liegt im Bereich des 10. Wiener Gemeindebezirks ([[Favoriten]]) und stellt eine natürliche Fortsetzung des [[Blumentals]] dar"}, {"kategorie": "", "text": "Geologisch gehört es zur Landschaft des [[Wiener]] Beckens und ist Teil des Übergangsbereichs zwischen den Erhebungen des Wienerbergs und den flacheren Teilen des Wiener Stadtgebiets"}, {"kategorie": "", "text": "Historisch und geografisch spielt das Reifental eine Rolle in der Abgrenzung und Verbindung der umliegenden Stadtteile. Es ist ein weniger bebautes und auch weniger bekanntes Gebiet, das vor allem durch seine Lage zwischen den beiden markanten Hügeln des Wienerbergs und des Laaer Bergs charakterisiert ist."}]'::jsonb, ''),
  ('hochwossagossn', 'Hochwossagossn', '', '', '', '', 'Hochwassergasse', '[{"kategorie": "allg.", "text": "\"ruhige Gasse im 23. Wiener Gemeindebezirk ([[Liesing]]), im Bezirksteil [[Inzersdorf]]\""}, {"kategorie": "", "text": "Der Name der Gasse erinnert an die wiederholten Hochwasserschäden, die der [[Liesingbach]] vor seiner Regulierung verursacht hat"}, {"kategorie": "", "text": "Vor der systematischen Regulierung des Liesingbaches war das Gebiet häufig von Überschwemmungen betroffen, was zu Schäden an Häusern und landwirtschaftlichen Flächen führte"}, {"kategorie": "", "text": "Die Benennung der Hochwassergasse dient daher als historisches Zeugnis für die einstige Bedrohung durch Hochwasser in diesem Gebiet und erinnert an die Herausforderungen, die die Bevölkerung durch die unregulierten Wasserverhältnisse erlebte"}, {"kategorie": "", "text": "An der Hochwassergasse befindet sich auch das [[Maria-Theresien-Schlössl]], ein barockes Landhaus aus der ersten Hälfte des 18. Jahrhunderts. Dieses denkmalgeschützte Gebäude liegt in einem weitläufigen Park und zählt zu den architektonischen Besonderheiten des Stadtteils Inzersdorf"}]'::jsonb, ''),
  ('maua', 'Maua', '', '', '', '', 'Mauer', '[{"kategorie": "allg.", "text": "\"Stadtteil im 23. Wiener Gemeindebezirk ([[Liesing]]) und eine der 89 Katastralgemeinden Wiens\""}, {"kategorie": "", "text": "Mauer umfasst eine Fläche von 639,57 Hektar und ist nach [[Inzersdorf]] der zweitgrößte Bezirksteil"}, {"kategorie": "", "text": "Mauer gilt als [[Heurigen-]] und Villenort am Rand des [[Wienerwalds]], ist für seine gehobene Wohnlage bekannt und grenzt im Norden anà Hietzing sowie an andere Bezirksteile [[Liesings]], wie [[Atzgersdorf]] und [[Kalksburg]]"}, {"kategorie": "", "text": "Der westliche, unbebaute Teil von Mauer ist vom [[Maurer]] Wald geprägt, einem Teil des Wienerwalds, der die höchsten Erhebungen des Gebiets, den [[Wilden]] Berg (369 m) und die [[Antonshöhe]] (356 m), umfasst"}, {"kategorie": "", "text": "Mauer hat eine lange Geschichte, die bis in die Jungsteinzeit zurückreicht. Funde eines 1929 entdeckten Hornsteinbergwerks auf der Antonshöhe deuten auf frühe menschliche Aktivitäten hin"}, {"kategorie": "", "text": "Die erste urkundliche Erwähnung des Orts erfolgte 1210unter dem Namen \"Můer\". Der alte Ort, ein Grabenangerdorf, erstreckte sich entlang des heutigen [[Maurer]] Hauptplatzes und an der [[Endresstraße]]"}, {"kategorie": "", "text": "Über die Jahrhunderte war Mauer besonders durch den [[Weinbau]] geprägt, der auch heute noch eine wichtige Rolle spielt. Im Biedermeier entwickelte sich der Ort zu einer beliebten Sommerfrische für wohlhabende Wiener"}, {"kategorie": "", "text": "Architektonisch bedeutsam sind in Mauer die Pfarrkirche St. Erhard ([[Maurer]] Pfarrkirche) und die moderne [[Wotrubakirche]] auf dem [[Georgenberg]], die zwischen 1974 und 1976 errichtet wurde"}, {"kategorie": "", "text": "Darüber hinaus sind mehrere historische Gebäude aus dem 17. und 18. Jahrhundert erhalten, darunter das [[Maurer]] Schlössel, das heute die Rudolf Steiner-Schule Wien-Mauer beherbergt"}, {"kategorie": "", "text": "Mauer wurde 1938 nach Wien eingemeindet, nachdem es zuvor eine selbstständige Gemeinde gewesen war. Heute leben etwa 17.000 Menschen in diesem Bezirksteil, der für seine malerische Landschaft, den Weinbau und die reiche Geschichte bekannt ist."}]'::jsonb, ''),
  ('fasslbeag', 'Fasslbeag', '', '', '', '', 'Faßlberg', '[{"kategorie": "", "text": "Er befindet sich im [[Maurer]] Wald, nahe der Grenze zum 23. Bezirk ([[Liesing]]), und liegt südlich des [[Lainzer]] Tiergartens"}, {"kategorie": "", "text": "Der Faßlberg ist Teil des [[Wienerwaldes]], der als nordöstlichster Ausläufer der Ostalpen gilt"}, {"kategorie": "", "text": "Östlich des Faßlbergs befinden sich die [[Antonshöhe]] und der [[Wilde]] Berg, im Nordwesten der [[Kleine]] Eichberg.\nDer [[Gütenbach]] sowie ein Quellbach fließen nördlich und westlich des Berges entlang"}, {"kategorie": "", "text": "Der Name Faßlberg stammt wahrscheinlich von der nahegelegenen Faßlwiese, die bereits 1819 als Fassel- und Stierwiese urkundlich erwähnt wurde. Der Name könnte von der Form der Wiese, die an ein Fass erinnert, oder von der mittelhochdeutschen Bezeichnung vasel (ein männliches Zuchttier, wie ein Stier oder Eber) abgeleitet sein."}]'::jsonb, ''),
  ('marswiisn', 'Marswiisn', '', '', '', '', 'Marswiese', '[{"kategorie": "allg.", "text": "\"Grünfläche im 17. Wiener Gemeindebezirk ([[Hernals]]), im Bezirksteil [[Neuwaldegg]], am Rande des [[Wienerwaldes]]\""}, {"kategorie": "", "text": "Sie ist Teil des [[Schwarzenbergparks]] und beherbergt das öffentliche Sportzentrum Marswiese, das von der Diözesansportgemeinschaft Wien betrieben wird"}, {"kategorie": "", "text": "Eine besondere Sehenswürdigkeit der Marswiese ist das Monument „Ruhender Mars“, eine Statue des Kriegsgottes Mars (auch Ares genannt), die zuvor im Lacy''schen Landschaftsgarten beim [[Schloss]] Neuwaldegg aufgestellt war"}, {"kategorie": "", "text": "Die Skulptur wurde 1774 von Johann Martin Fischer angefertigt und ist eine Kopie des antiken Motivs Ares Ludovisi"}, {"kategorie": "", "text": "Das Motiv des ruhenden Kriegsgottes stammt vermutlich aus dem 4. Jahrhundert v. Chr. und wurde von den griechischen Bildhauern Skopas oder Lysipp entwickelt und in der römischen Zeit mehrfach kopiert."}]'::jsonb, ''),
  ('guetnboch', 'Gütnboch', '', '', '', '', 'Gütenbach', '[{"kategorie": "allg.", "text": "\"Bach in den Wiener Gemeindebezirken [[Hietzing]] (13. Bezirk) und [[Liesing]] (23. Bezirk) und ein Zubringer des [[Liesingbachs]]\""}, {"kategorie": "", "text": "Der Gütenbach hat eine Länge von 6930 Metern. Er entspringt an den Hängen des nahe der Wiener Stadgrenze liegenden Dreihufeisenbergs in Niederösterreich und fließt im Oberlauf durch das Naturschutzgebiet [[Lainzer]] Tiergarten im 13. Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Der Gütenbach verlässt den Lainzer Tiergarten durch das Gütenbachtor und verläuft durch das Wald- und Wiesengebiet des Bezirksteils [[Kalksburg]] im 23. Bezirk ([[Liesing]]), der zum Landschaftsschutzgebiet Liesing gehört. Im Unterlauf fließt der Bach durch besiedeltes Gebiet, verlässt die Flyschzone und erreicht die Nördlichen Kalkvoralpen, bevor er schließlich linksseitig in den Liesingbach mündet"}, {"kategorie": "", "text": "Der Gütenbach wird als eine der möglichen Quellen für die ehemalige römische Wasserleitung zum Legionslager [[Vindobona]] am Oberlauf des [[Liesingbaches]] vermutet"}, {"kategorie": "", "text": "Im Mündungsbereich wurde bereits im 18. Jahrhundert ein Wehr errichtet, das Wasser für einen Mühlbach ableitete. Um 1912 wurde der Bach vollständig in diesen Mühlbach eingeleitet"}, {"kategorie": "", "text": "Der Mündungsabschnitt wurde bis 2010 begradigt und stark verbaut. Eine Renaturierung dieses Abschnitts erfolgte 2016, wobei die Pflasterung im Bachbett entfernt, Flachwasserbereiche eingerichtet und neue Bäume gepflanzt wurden."}]'::jsonb, ''),
  ('guetnbochtoi', 'Gütnbochtoi', '', '', '', '', 'Gütenbachtal', '[{"kategorie": "allg.", "text": "\"Tal im südwestlichen Teil des 23. Wiener Gemeindebezirks ([[Liesing]]), das nach dem dort verlaufenden [[Gütenbach]] benannt ist\""}, {"kategorie": "", "text": "Es erstreckt sich im Bereich des [[Maurer]] Waldes und gehört zur naturnahen Landschaft des [[Wienerwalds]]"}, {"kategorie": "", "text": "Das Gütenbachtal liegt in der Nähe bedeutender geografischer Punkte wie dem [[Wilden]] Berg und der [[Antonshöhe]]"}, {"kategorie": "", "text": "Durch das Tal fließt der [[Gütenbach]], ein Zubringer des [[Liesingbachs]]"}, {"kategorie": "", "text": "Das Tal ist u.a. auch geprägt von den mäandernden Abschnitten des [[Gütenbachs]], der in der Region eine bedeutende Rolle für das Ökosystem spielt."}]'::jsonb, ''),
  ('antonsheechn', 'Antonsheechn', '', '', '', '', 'Antonshöhe', '[{"kategorie": "allg.", "text": "\"356 Meter hohe Erhebung im Bezirksteil [[Mauer]] des 23. Wiener Gemeindebezirks ([[Liesing]]), früher auch \"Hauswurzhügel\" genannt"}, {"kategorie": "", "text": "Die Antonshöhe liegt im [[Maurer]] Wald und beherbergt den aufgelassenen Steinbruch Mauer-Antonshöhe, der als das älteste Industriedenkmal Österreichs gilt"}, {"kategorie": "", "text": "Nördlich der Antonshöhe liegt der [[Wilde]] Berg, im Südosten der [[Georgenberg]] und im Südwesten das [[Gütenbachtal]]"}, {"kategorie": "", "text": "Benannt wurde sie nach Anton Ölzelt dem Älteren, einem österreichischen Baumeister (* 7. Juni 1817 in Inzersdorf; † 12. Oktober 1875 in [[Mauer]])"}, {"kategorie": "", "text": "Der Steinbruch auf der Antonshöhe war bereits in der Jungsteinzeit von Bedeutung. 1929/1930 wurden bei Sprengungen mehrere Abbauschächte entdeckt, die sogenannten Mardellengruben (=wassergefüllte Geländemulden):  6. Hier wurde Rohmaterial wie Hornstein und Radiolarit in rötlich-braunen und grünlichen Tönen abgebaut, das für die Herstellung von Werkzeugen verwendet wurde"}, {"kategorie": "", "text": "Die Antonshöhe gehört zu den bedeutendsten frühzeitlichen Bergbaustätten Europas, da dort begehrter Silex abgebaut wurde. Die archäologischen Untersuchungen wurden von Josef Bayer vom [[Naturhistorischen]] Museum Wien geleitet, zu dessen Ehren ein Gedenkstein beim Rasthaus Schießstätte am [[Wilden]] Berg aufgestellt wurde"}, {"kategorie": "", "text": "Die [[Feuersteingasse]] in [[Mauer]] wurde 1929 nach dieser archäologischen Stätte benannt."}]'::jsonb, ''),
  ('feiaschdaagossn', 'Feiaschdaagossn', '', '', '', '', 'Feuersteingasse', '[{"kategorie": "allg.", "text": "ruhige Straße im Bezirksteil [[Mauer]] des 23. Wiener Gemeindebezirks ([[Liesing]])"}, {"kategorie": "", "text": "Sie wurde im Jahr 1929 nach der archäologischen Stätte auf der [[Antonshöhe]] benannt, wo in der Jungsteinzeit Hornstein und Radiolarit abgebaut wurden. Diese Gesteinsarten, auch als Feuerstein bekannt, dienten der Herstellung von Werkzeugen und wurden weit gehandelt"}, {"kategorie": "", "text": "Die Benennung der Gasse erinnert an die archäologischen Funde, die im ehemaligen Steinbruch auf der Antonshöhe entdeckt wurden. Hier wurde bereits vor etwa 7.500 Jahren Hornstein gewonnen, der als wichtiger Rohstoff für die Menschen der Linearbandkeramik-Kultur und anderer prähistorischer Kulturen galt."}]'::jsonb, ''),
  ('kaisazipf', 'Kaisazipf', '', '', '', '', 'Kaiserzipf', '[{"kategorie": "allg.", "text": "\"339 Meter hohe, bewaldete Anhöhe im 13. Wiener Gemeindebezirk ([[Hietzing]]), im [[Lainzer]] Tiergarten, nahe der Grenze zur niederösterreichischen Gemeinde Breitenfurt\""}, {"kategorie": "", "text": "Der Kaiserzipf liegt im südwestlichen Teil von Hietzing und gehört zum [[Wienerwald]], dem nordöstlichsten Ausläufer der Ostalpen"}, {"kategorie": "", "text": "Im Norden des Kaiserzipfs liegt die [[Faßlwiese]], im Süden der [[Kaufberg]]. Westlich grenzt der Laaber Kaiserzipf, östlich der [[Kleine]] Eichberg an den Kaiserzipf. Der [[Gütenbach]] umfließt die Anhöhe im Nordosten"}, {"kategorie": "", "text": "Der Name Kaiserzipf wurde erstmals 1788 urkundlich als \"Kayerzipf\" erwähnt und später, im Jahr 1819, in seiner heutigen Form genannt"}, {"kategorie": "", "text": "Der Name leitet sich vom ehemaligen Besitzer des Waldstücks, dem kaiserlichen Hof, ab. Der Begriff Zipf bezieht sich auf die spitz zulaufende Form des Gebietes."}]'::jsonb, ''),
  ('kaufbeag', 'Kaufbeag', '', '', '', '', 'Kaufberg', '[{"kategorie": "allg.", "text": "\"bewaldete Anhöhe im 13. Wiener Gemeindebezirk ([[Hietzing]]), gelegen im südwestlichen Teil des Bezirks, nahe der Grenze zur niederösterreichischen Gemeinde Breitenfurt\""}, {"kategorie": "", "text": "Der Kaufberg umfasst die beiden Gipfel \"Vorderer Kaufberg\" (341m) und \"Hinterer Kaufberg\" (413m), welche zum [[Wienerwald]] gehören, dem nordöstlichsten Ausläufer der Ostalpen"}, {"kategorie": "", "text": "Der Kaufberg liegt südlich des [[Kaiserzipfs]] und wird von diesem im Norden begrenzt. Im Westen grenzt der Laaber Kaiserzipf, und östlich liegt der [[Kleine]] Eichberg"}, {"kategorie": "", "text": "Der bewaldete Hügel ist eingebettet in das dichte Waldgebiet des [[Lainzer]] Tiergartens, das eine bedeutende Rolle für den Naturschutz und die Erholung in Wien spielt."}]'::jsonb, ''),
  ('koitbruendlbeag', 'Koitbründlbeag', '', '', '', '', 'Kaltbründlberg', '[{"kategorie": "allg.", "text": "\"zweithöchster Berg des 13. Wiener Gemeindebezirks ([[Hietzing]]) mit einer Höhe von 508 Metern\""}, {"kategorie": "", "text": "Auf seiner höchsten Kuppe befindet sich die [[Hubertuswarte]], ein Aussichtsturm"}, {"kategorie": "", "text": "Der Kaltbründlberg liegt am südwestlichen Rand von Hietzing in der Katastralgemeinde [[Auhof]] und gehört zum [[Lainzer]] Tiergarten. Er ist Teil des [[Wienerwaldes]], der den nordöstlichsten Ausläufer der Ostalpen bildet"}, {"kategorie": "", "text": "Südöstlich des Berges liegt der [[Mittlere]] Eichberg, und etwa 1 Kilometer westlich befindet sich der [[Hornauskogel]]. An den südlichen Abhängen entspringen Teile des Quellgebiets des [[Gütenbachs]], der später in die Reiche Liesing mündet"}, {"kategorie": "", "text": "Der Name Kaltbründlberg wurde erstmals 1925 urkundlich erwähnt, ursprünglich als Kaltbrünnlberg bzw. Kalter Brünnlberg. Er leitet sich von der im Süden gelegenen Kaltbründlwiese ab, die bereits seit 1788 als Brünndlwiese bekannt ist. Diese Wiese erhielt ihren Namen durch eine kalte Quelle des [[Gütenbachs]], die sich am östlichen Rand der Wiese befindet."}]'::jsonb, '')
